window.POEM_DB=window.POEM_DB||{};POEM_DB["yuan_025"]={"n":"黄玠","dyn":"元","poems":[{"t":"拟古 其一","f":"曲","c":["龙马负灵图，八卦开人文。","天运当寅中，民时方大昕。","制字乃未多，所言为典坟。","一往数千载，怀哉圣神君。"]},{"t":"拟古 其二","f":"曲","c":["翳林无阳土，暗谷多下泉。","登山履众险，险尽见杪颠。","人居物物中，物物能蔽天。","将身出物表，万象始昭然。"]},{"t":"拟古 其三","f":"曲","c":["一气成岁功，孰为四分之。","遂使春木荣，不知秋叶萎。","天道自有初，物命亦有司。","任运得吾性，无为无不为。"]},{"t":"拟古 其四","f":"曲","c":["天高九万里，疾若弩矢驰。","白日犹在下，况尔众物为。","翾羽刷俊彩，强欲凌空飞。","去人苦不远，但使见者疑。"]},{"t":"感怀 其一","f":"曲","c":["积阴不可扫，积懑不可道。","君子所可道，小人以为嬲。","世事终渺茫，物情慢衰老。","归来日未昳，自去庭中草。"]},{"t":"感怀 其二","f":"曲","c":["仙人大还丹，可用更凡胎。","举世不谓然，逝矣谁能哀。","万事唯有醉，奴子抱琴来。","十倍李供奉，一饮三千杯。"]},{"t":"感怀 其三","f":"曲","c":["矩步恒彳亍，捷走能千回。","感彼元发化，聊复少衔杯。","阴草夏即苑，阳花冬亦开。","天序自有定，不是偶然来。"]},{"t":"感怀 其四","f":"曲","c":["有酒可用醑，无酒我当酤。","天运岁益差，人事日不如。","羽虫何多言，木叶已无数。","凄其众草晚，乐与佳菊遇。"]},{"t":"感怀 其五","f":"曲","c":["物蠹岂有极，造物难为工。","我将剔除之，刺芒铦若锋。","小枝食已尽，大枝旋复空。","虫多饱即死，花落为枯丛。"]},{"t":"感怀 其六","f":"曲","c":["盆中梅树子，为尔可怜生。","寒泥不五斗，勿与大块争。","移置池水头，照影池上冫。","和冫嚼花蕊，天地无馀清。"]},{"t":"感怀 其七","f":"曲","c":["娼鸟不可驯，娼女不可亲。","野性自难定，岂知爱其身。","千金买少妾，属托在他人。","譬如道旁花，竟是为谁春。"]},{"t":"感怀 其八","f":"曲","c":["驽马少良驹，淑媛多令子。","大易重咸恒，关雎明谨始。","橘树生南州，渡江即为枳。","地气使之然，如何论天理。"]},{"t":"感怀 其九","f":"曲","c":["江左言风流，王谢为称首。","谧既坐奸回，澹亦亏节守。","清谈本废事，何物非刍狗。","不忍书义熙，侃独有佳后。"]},{"t":"感怀 其十","f":"曲","c":["子云投阁生，绿珠坠楼死。","事主心弗移，不若一婢子。","哀哀莽大夫，千古秽青史。","草元数万言，焉用识奇字。"]},{"t":"感怀 其十一","f":"曲","c":["燔肉既不至，孔子辄去鲁。","醴酒复不设，穆生亦辞楚。","古人道义交，政在慎出处。","寥哉圣贤心，夫岂餔啜故。"]},{"t":"感怀 其十二","f":"曲","c":["花开君勿折，花谢君勿扫。","扫花伤花心，折花畏花嫐。","但令尊有酒，中怀得倾倒。","从花自开谢，开好谢复好。"]},{"t":"感怀 其十三","f":"曲","c":["上客有冯驩，故吏有任安。","二子久已死，益见交道难。","软语相媚悦，颠倒若转丸。","孰云是可忍，怒发为冲冠。"]},{"t":"感怀 其十四","f":"曲","c":["南州辫发儿，相从事觚椠。","陈遵好尺牍，暇日聊口占。","悠悠历岁年，寒暑若病痁。","道德负初心，谁独受针砭。"]},{"t":"感怀 其十五","f":"曲","c":["客有千金儿，过我十尺舍。","狭隘不可留，飞丸出弹射。","腰下雕玉螭，粹好绝衅罅。","信美非所珍，聊足以相诧。"]},{"t":"感怀 其十六","f":"曲","c":["朱弦有遗音，琅然动清泛。","自喜若弗胜，入耳何沨沨。","君子道吾常，哤俗多杂儳。","但念赏人稀，不知听者厌。"]},{"t":"感怀 其十七","f":"曲","c":["白日何瞢瞢，人中有枭獍。","酖毒不可怀，犹将恣酣醟。","司命主督察，雷公布天令。","慎尔恐自戕，微我相诟病。"]},{"t":"感怀 其十八","f":"曲","c":["儒有席上珍，把玩足无厌。","梅花虽苦寒，其中自清赡。","富贵如燎毛，炙手方炎炎。","贪恋之谓何，仰天一长欠。"]},{"t":"感怀 其十九","f":"曲","c":["昂然三尺松，种之五斗盎。","俯身就嵌石，毛发如鬼状。","虽蒙华屋居，故性终木强。","谁当宣其郁，使彼得疏畅。"]},{"t":"感怀 其二十","f":"曲","c":["久客念还家，还家复如客。","行李未及安，期日相促迫。","勿匆问衣襟，草草箧书册。","终岁恒若斯，几何头不白。"]},{"t":"题吴季良东明轩","f":"曲","c":["朝日出旸谷，照我轩东荣。","煌煌天光发，湛湛旦气清。","定志息喧杂，澄心养虚灵。","八窗启扃钥，万象生光明。"]},{"t":"赋顾梅西煮雪","f":"曲","c":["摇竹取残雪，松声动寒吹。","金怀少馀欢，石鼎作雅事。","极清超水品，至淡出天味。","行过梅花西，唤起幽人睡。"]},{"t":"采莲女","f":"曲","c":["川日出已高，江霏散如雾。","但闻采莲曲，不知采莲处。","双双相思鸟，飞上相思树。","幽人空尔怀，欲往畏多露。"]},{"t":"寄胡伯衡兼呈叔父元理元美二首 其一","f":"曲","c":["忆昔少年日，慷慨赋远游。","晨起揽白须，始知天地秋。","寒云去雁断，落木穷猿愁。","亲故各异方，谁当慰淹留。","此邦非吾土，怅望登兹楼。","长歌动幽愤，汗漫不可收。"]},{"t":"寄胡伯衡兼呈叔父元理元美二首 其二","f":"曲","c":["阳鸟尚谋食，候虫犹念衣。","口体见驱迫，使我远别离。","历历路半千，迢迢江两涯。","悠悠去乡邑，往往见絷縻。","年衰酒况恶，引饮不满卮。","形影相嘅惜，恐为时所悲。","弁山非故山，怆然寄幽期。","馀生苟木陨，犹及尔东归。"]},{"t":"题章德?兰","f":"曲","c":["竹树何蘙荟，蕙兰自奇芬。","水墨写清影，犹疑见湘原。","欲持一卮酒，酹此千岁魂。","但恐醉中意，难与醒者言。"]},{"t":"赋傅伯玉来青轩","f":"曲","c":["两山送青来，与人终日閒。","爽气逼眉宇，不似在尘间。","仰观天中云，扰扰去不还。","始知静者佳，取琴当户弹。"]},{"t":"南堂偶成似卫耕间先生","f":"曲","c":["倚阑看池水，池水清若空。","烟沉树色底，日行云影中。","翾羽晞薄雾，游丝汎光风。","跃鱼自幽潜，岂望能为龙。","才劣不任官，力弱不任农。","清世有华民，我辰非不逄。"]},{"t":"赋陆子敬旧时月色亭","f":"曲","c":["古月即已旧，今月乃更新。","解后见颜色，梅花如故人。","挽彼檐下枝，挂我头上巾。","摘花不插发，踏月走千巡。","横笛且勿吹，良夜亦易晨。","恒恐明日至，使我迹复陈。","愿因白免公，托根冫雪轮。","结子近琼楼，永与桂树亲。"]},{"t":"月下独酌似谢季初叔久兄弟","f":"曲","c":["风休露欲下，云过月如走。","一尊良夜初，万事中年后。","大白真仙人，俗客匪其偶。","孤斟不成欢，引影作三友。","我今笑问影，颇亦解事否。","既能随我身，胡不开尔口。","倾杯月入怀，停杯月在手。","此月岂真月，不饮复何有。"]},{"t":"寄衍上人索画兰 其一","f":"曲","c":["薄言采兰蘤，兰叶□□□。","□□□人远，僻处荒山原。","崇炫非素心，澹泊性所存。","亦同桃李春，不同桃李繁。"]},{"t":"寄衍上人索画兰 其二","f":"曲","c":["众芳非不佳，蕙茝尤楚楚。","亦荷雨露私，如何在榛莽。","庶将展微劳，揽置群玉府。","时我方未遑，临风独延伫。"]},{"t":"寄衍上人索画兰 其三","f":"曲","c":["渔子荡两桨，来从湘水滨。","手抱青兰枝，言报山中春。","问我日日醉，恐贻楚叟嗔。","独醒不在酒，举手谢野人。"]},{"t":"寄衍上人索画兰 其四","f":"曲","c":["日出跻北林，日入下西澨。","幽芳隔远水，水寒不可厉。","归来看画图，潇洒美风制。","万事何必真，聊与尔同世。"]},{"t":"游幻住庵留赠月千江上人 其一","f":"曲","c":["出郭动柔橹，春花始班班。","俯舷照清流，正见衰病颜。","形影自相笑，浮沉人两间。","胡能即有定，波荡不得閒。"]},{"t":"游幻住庵留赠月千江上人 其二","f":"曲","c":["村雨农事殷，溪晴客衣暖。","佳人同綵舟，沿洄绕芳甸。","吴蚕近三眠，鲁桑连百畹。","相将采白蘋，日与春俱晚。"]},{"t":"游幻住庵留赠月千江上人 其三","f":"曲","c":["既雨天复佳，鸣鸟声故故。","前溪春已深，劝我脱布裤。","刺篙乱清涟，艇子入浦溆。","我裤不用脱，汝自顾汝妇。"]},{"t":"游幻住庵留赠月千江上人 其四","f":"曲","c":["维时桃始华，野眺欣有睹。","沿洄度桑隰，迤逦见谷土。","山虚龙出云，谷暖鸟鸣雨。","来耨良足勤，力薄奈何汝。"]},{"t":"谢长源为余言燕子事有感","f":"曲","c":["旧雌有众雏，新雌来杀之。","蒺藜刺中肠，并死无一遗。","持筸逐娼鸟，恶土污人衣。","彼雄诚不才，怨心当语谁。","祥览令我惧，伋寿令我思。","物态尚如是，世情良足悲。"]},{"t":"慎勿买良田","f":"曲","c":["慎勿买良田，良田有豺虎。","豺虎不汝食，官司推剥汝。","公廪多急输，里正遭箠楚。","肉尽即见骨，家破无死所。","茹蔊何必辛，茹荼何必苦。","伤哉浙水民，困此一犁土。"]},{"t":"与戴彦季张和伦游南山玲珑洞","f":"曲","c":["放舟出清苕，鸣橹声了牙。","历历览胜绝，行行入幽遐。","玲珑洞穴古，疑有仙人家。","清风石上起，吹老良姜花。"]},{"t":"与韩介石闻人梅涧游黄龙洞","f":"曲","c":["龙君所幽潜，嵌空若眢井。","投石风转雷，股栗怯深迥。","僮奴夸捷走，啸呼已绝顶。","升高只自危，聊复罢吾兴。"]},{"t":"次韵孙尤实言诗","f":"曲","c":["佳诗如饮泉，一寒乃清真。","妙趣欲无我，宁复有袭因。","学之三十年，同光犹隙尘。","扰扰共高下，未足轻众人。","多忤言可忘，薄奉气乃醇。","羲黄复何心，适当天地春。"]},{"t":"与梁邦彦对雪饮酒禁体","f":"曲","c":["五精阐嘉瑞，一白遍林薮。","飘洒集众妙，点缀出群有。","覆藏失垢污，摧压见节守。","岁华乃尔清，夜色不得黝。","僮奴掖醉归，迹足没已厚。","人生几两屐，素发一搔首。"]},{"t":"移舟","f":"曲","c":["移舟发江夕，远浦入双树。","烓灶动烟火，野宿在中露。","波月光鳞鳞，川霏杂轻雾。","濯手乱繁星，水禽忽飞去。"]},{"t":"素庵旅次","f":"曲","c":["积雨敛溽氛，光风开日华。","先生澹怀士，结屋如兰阇。","庭下昌歜根，门前射千花。","□□□□□，□香闻煮茶。"]},{"t":"似海云使君","f":"曲","c":["佳云满蓬莱，常具五彩色。","溟涬一气浮，空濛万川积。","合散自有时，变化忽无迹。","念彼霖雨功，宜使蛟龙得。"]},{"t":"示男曾","f":"曲","c":["昔别甬上居，薄游吴中郡。","耻从俗子言，恐失名家韵。","生儿似阿堆，颇亦存轨训。","常疑习气迁，思与学宫近。"]},{"t":"当湖早行","f":"曲","c":["离离海气分，皛皛晨光发。","舟楫远相呼，川途正纡折。","翕目聊假寐，凉飙动毛发。","客路绕天涯，人家在林樾。"]},{"t":"题画山水似盛子昭 其一","f":"曲","c":["冉冉山上云，累累水中石。","梢梢林莽高，黯黯崖谷黑。","东冈特秀绝，拔地起千尺。","突兀众峰间，犹是太古色。"]},{"t":"题画山水似盛子昭 其二","f":"曲","c":["连山根插江，江碧石齿齿。","层颠高出云，老树下压水。","岩扉俯深迥，磴道陟纡委。","欲持一壶酒，慰彼幽栖子。"]},{"t":"题画山水似盛子昭 其三","f":"曲","c":["前山如立槊，后山如倚较。","远近千万山，斗绝入牛角。","矾头积磊砢，石面斗硗确。","是中无征徭，民俗犹愿悫。"]},{"t":"题画山水似盛子昭 其四","f":"曲","c":["回峰危欲堕，峭径深可入。","萦纡度壁坞，杳窕去井邑。","泉悬净练明，崖拥积铁涩。","缅怀贞白君，相从负云笈。"]},{"t":"题商山图","f":"曲","c":["美宦少宁居，良田多赋率。","曼肤白如瓠，仍防污鈇锧。","所以商山翁，深逃入堂密。","蔽芾皆美枞，不睹长安日。","扬扬大逄衣，剪剪小第室。","门巷既荒寒，器具犹古质。","渴即引井泉，饥或餐木实。","微我异枭鸾，从人自凫乙。","平生紫芝曲，久不屈此膝。","须眉各皓然，一为天下出。"]},{"t":"自赞并赠写真陈伯玉","f":"曲","c":["有形本皆幻，聊与影相从。","于兹未能忘，更欲求其同。","我神夫岂远，故在阿堵中。","灵景合内外，逍遥方未终。"]},{"t":"张伯寿煮石窝清坐","f":"曲","c":["客主心两忘，清坐对荒寂。","吹火出青藜，拾薪煮白石。","倚阑荷气凉，移床竹阴夕。","素发共飘萧，风期似畴昔。"]},{"t":"黄一峰莫莫斋","f":"曲","c":["莫莫重莫莫，车轮生四角。","岐路满天涯，归人已林壑。","若华能照夜，蓂草知合朔。","物有秀而灵，唯吾贵淳朴。"]},{"t":"寒夜","f":"曲","c":["寥寥遥夜清，霍霍流景急。","馀生若断绪，棼糺不可缉。","屋高寒影孤，窗虚雨声集。","僮奴懒欲休，独背残灯立。"]},{"t":"称大人寿","f":"曲","c":["大人心坦坦，大人猊雍雍。","凡此故宜寿，始是八十翁。","左雄多后福，卓茂本宽中。","遂当享耄期，妙颜若芙蓉。"]},{"t":"曹继善安雅斋","f":"曲","c":["山行常蹇蹇，水行夷且宛。","轻舟逐流水，晨色犹漫漶。","雅道乐安恬，幽人有园馆。","竹素纷委积，轩楹飒闲远。","微官厌卑渫，馀日甘冗散。","衣食岂馀饶，菅麻与蒲?。","生儿似江革，辞气尤愿款。","清吟楷法书，作字特遒婉。","嘅彼云海禽，毛羽何丰满。","去去迷所休，恒忧百年短。"]},{"t":"听刘希孟琴","f":"曲","c":["公子青藜客，寄怀在兹琴。","歌吟杂操弄，将老嗜益深。","愔愔古大雅，如玉复如金。","下指舒以徐，三叹有遗音。","虚堂初夜凉，相为洗烦心。","小瓮酒可得，与君留月斟。"]},{"t":"答韩廷玉问诗","f":"曲","c":["学诗自有律，才流必经通。","咏歌成文章，譬若水与风。","茫茫沃云日，衮衮吹鱼龙。","触激从所遇，万变何可同。","恬淡有馀韵，奇崛难为工。","恒存言外意，趣味斯无穷。"]},{"t":"竹亭用本韵","f":"曲","c":["绕霤竹万挺，昼日起暝色。","允矣幽人贞，怀哉君子德。","淡食度清朝，微吟答佳夕。","遗我青琅玕，报之双水碧。"]},{"t":"题韩介石所藏盛子昭画","f":"曲","c":["隆隆大谷深，挺挺嘉木秀。","崇冈拆阴壑，悬水落长霤。","槎牙松颠回，侧塞石角斗。","来者岂阮生，尚尔冠服旧。","清啸满空山，高人在危构。","胡不从之居，分瓢饮云窦。"]},{"t":"章俊甫水心亭","f":"曲","c":["羽客恶涂■，鲛人乐水居。","亭子在中沚，清漪涵四除。","隔花闻好鸟，俯阑见游鱼。","悠悠川上意，雅咏时相娱。"]},{"t":"与琏市巡检杨德新","f":"曲","c":["觟䚦徒有角，用鸷不如鹗。","麒麟岂无趾，走险不如猎。","看君好眉宇，兰台瑩而博。","子云识奇字，安能效巡捉。","盗律如牛毛，民风日偷薄。","弯弓欲谁拟，聊复动鸣?。","烟疏榆柳村，水深萑蒲泽。","代者久不来，淹留竟何乐。"]},{"t":"重来吴兴有怀松雪斋","f":"曲","c":["采芳须得兰，斩坚须得檀。","怀哉古君子，感此岁欲单。","青山如韎韐，逶?起林峦。","文立早有正，气一何郁盘。","云来松雪春，云去松雪寒。","藻翰虽不绝，门樾今稀残。","尚思灯火夕，舛讹见砭弹。","厚意何以报，抱志空长叹。"]},{"t":"赠医士叶古斋","f":"曲","c":["昔者帝轩辕，驾言师赤松。","相教服水玉，问道崆峒宫。","文字尽科斗，故是开天功。","顾谓鬼臾区，妙契将无同。","灵枢发奥旨，元气春融融。","山川入揽挹，草木臭味通。","悬壶隐东市，愧尔卖药翁。","上下数千载，犹在一日中。"]},{"t":"听周子固琴","f":"曲","c":["周郎妙音解，矑子光射人。","山水有雅曲，徽音得其真。","神閒应接暇，气和节调匀。","鱼鸟亦飞跃，云风忽轮囷。","令我不能去，永怀愿相亲。"]},{"t":"拟送张子长赴史馆","f":"曲","c":["陈志称秽史，汉绪遂中绝。","不如诵杜诗，忠槩何惯切。","我将操玉斧，腾飞入明月。","斮彼白兔毫，制为董狐笔。","送子万里行，聊用资作述。","大义或有乖，慎尔宁勿勿。"]},{"t":"邵复孺映雪斋","f":"曲","c":["邵子书有癖，一寒四窗静。","举手倒执经，夜映雪色冷。","侧睨生墨光，天地无遗景。","希功厚积馀，思与古人并。"]},{"t":"俞子昭山月轩","f":"曲","c":["山月出未高，烂如大银槃。","及其当天中，小于冰一丸。","我将问郁仪，青冥风露寒。","远近且莫解，况尔阙与抟。","兹轩特可喜，倚阑终日看。","常疑猛虎啸，惊起女乘鸾。"]},{"t":"大雪有怀北中亲友","f":"曲","c":["南州三日雪，堕地为坚冰。","念我骨肉亲，束书向幽并。","马寒车折轴，岁晚不得宁。","仰观浮云驰，缅焉寄深情。"]},{"t":"雪壑海云使君所自号也 其一","f":"曲","c":["云来雪壑阴，云去雪壑明。","未见雪壑面，已闻雪壑名。","岂谓众皆浊，常使我独清。"]},{"t":"雪壑海云使君所自号也 其二","f":"曲","c":["云去雪壑明，云来雪壑阴。","不从雪壑游，不知雪壑心。","家世本钟鼎，志愿在山林。"]},{"t":"农舍","f":"曲","c":["农舍如鸡栖，稚子煦檐隙。","陂田不作垄，野水深及壁。","树老夕照黄，草枯寒烟白。","鱼罛设处处，民有食菜色。"]},{"t":"题郭天锡云山图","f":"曲","c":["翘翘山有木，翳翳林有谷。","雨气作深云，新阴如膏沐。","夫岂无居人，诛茅结溪屋。","幽栖不出户，野塘春水绿。"]},{"t":"张子英闲止斋","f":"曲","c":["筑室依甘泉，兰若满中沚。","采掇子为谁，杂佩玉橤橤。","拟步即市门，行行行且已。","西山有爽气，朝来眉睫里。","尘土一振衣，城郭清风起。","馀习久未忘，篇帙故纷委。","方床十尺舍，亦有乌皮几。","弹琴碧云合，饮酒白日靡。","时时盍朋簪，森然会群理。","领悟不必多，凡百苟今是。","潜也何人斯，良犹慕之耳。","既醉旋复醒，逍遥尔闲止。"]},{"t":"闻人梅涧垩室","f":"曲","c":["垩室生白光，方广逾一丈。","真元不受采，太素宁有象。","端居静众念，纳气入晃朗。","翛翛尘尾拂，济济鹤羽氅。","高灯石月悬，浓熏暖云上。","深雪拥梅花，思致足写仿。"]},{"t":"琏市有双桂庙里父老云嵇司徒女堕井死树有灵怪人家喜庆歌乐之事必祭之如喜神云","f":"曲","c":["庙前双桂树，柯叶恒蓊蓊。","不知何王世，司徒嵇氏冢。","女郎井中死，灵怪相唝恐。","自谓得水仙，谁当觉群懵。"]},{"t":"题李紫筼墨本竹枝","f":"曲","c":["郑谷爱吟诗，夜闻岩竹折。","至今石上影，犹带山中雪。","刻彫妙入神，馀情寄乀丿。","永怀贞白君，终身惟素节。"]},{"t":"月食","f":"曲","c":["彼月有食之，死魄无遗光。","至阴自肃肃，岂曰敢亢阳。","天中有闇虚，无乃俄相当。","奄忽就灭没，见者为怜伤。","几欲张威弧，举矢射天狼。","恐非圣人意，伫立但徊徨。"]},{"t":"赠祷旱彭生黄仲珍家僮也","f":"曲","c":["旱魃忍为虐，祠龙拜灵星。","踉蹡作禹步，符摄有依凭。","神官与鬼吏，霍霍见使令。","雷从几上起，云逐剑口生。","一雨滂若注，多稼勃已兴。","自彼元气神，惠答如响应。"]},{"t":"题吕德常所藏云西雪山小景","f":"曲","c":["前冈崭如削，后巘旋若顾。","溪寒?嵊晚，雪没剡中路。","将无乘兴人，过彼幽栖处。","应待月华生，却棹扁舟去。"]},{"t":"水枕","f":"曲","c":["水枕欹独眠，凉波荡柔橹。","仰观天宇高，默默心自语。","清云不蔽日，浊云乃多雨。","造物本无为，一气异消聚。"]},{"t":"华亭教谕张伯元归钱塘","f":"曲","c":["恻恻重恻恻，舟舵动行色。","岁晚念尊亲，华亭有归客。","琴清孤月白，酒尽众山碧。","楼阁倚高寒，江空帆影侧。"]},{"t":"次韵曹教谕见寄 其一","f":"曲","c":["凉风发秋夕，落木振疏阴。","相思在咫尺，两契同一心。","徽弦不下指，宁我有遗音。","梧桐生下泽，几时成凤林。"]},{"t":"次韵曹教谕见寄 其二","f":"曲","c":["蹀躞双远游，独绕庭中树。","与世欲并臧，行行迷所遇。","有客吹洞箫，如泣亦如诉。","花月满良宵，如何此虚度。"]},{"t":"僮奴山中归","f":"曲","c":["僮奴山中归，为言山上松。","昔日摇鼠尾，于今如稚龙。","结根依崇阿，秀色排霜风。","可待生茯苓，持以寿吾翁。"]},{"t":"石塘观鱼似谢伯昭伯礼","f":"曲","c":["嘈嘈冰戛川，濊濊鱼在罧。","潜逃欲无所，渔罟来闯闯。","鳞鬐见蹙迫，首尾相藉枕。","猿穷不择木，鹿死不择音。","尔鱼自有神，胡不游广深。"]},{"t":"五仄体思卫立礼作","f":"曲","c":["我友卫伯子，履道坦若砥。","瞪目视薄俗，足不涉市里。","客至设雅饮，屡屡不可已。","重尔意爱笃，使我独仰止。","梦寐若有觌，寤叹隔远水。","落月照屋梠，睟面玉色起。"]},{"t":"次韵章俊甫训子","f":"曲","c":["前朝名宦孙，承家以清白。","五缫玉有光，百鍊金出色。","升堂奉慈亲，甘芳极娱适。","推欢及司气，兄弟仍翕翕。","平生子孙念，况肯勤戒饬。","叔郎烱双矑，器量牛可食。","伯郎作大字，日费三斗墨。","怒骂静不闻，举步垂轨则。","穊种必厚收，譬彼农力穑。","通才识细务，至理明大率。","洪垆万石钟，重自铢两积。","众口所称叹，天心为忻怿。","每怜机巧徒，何殊沐猴棘。","较智三十里，百失希一得。","晤言篱下英，留芳待秋夕。","晚节将益佳，于公有阴德。"]},{"t":"王官谷听泉","f":"曲","c":["援琴俯寒泉，琅然动幽听。","写彼石上流，寄此山中兴。","耵聍喧杂空，潺湲清响应。","翻将羽衣曲，更作龟兹咏。"]},{"t":"与赵都事初心","f":"曲","c":["白日照素商，朱草合秋朔。","参旗久未起，举头见晨角。","南中有佳士，风度甚高邈。","愿生双羽翰，旦莫往数数。"]},{"t":"与衍上人道原","f":"曲","c":["树本连百围，萝蔓丝成结。","回川缭崇构，栾栌隐深樾。","湍驶泉响急，径险石色滑。","可容许询辈，清心共禅悦。"]},{"t":"陈益之壶中","f":"曲","c":["仙翁不知年，一壶悬太空。","晨朝出卖药，日夕入其中。","虽与市人处，不与市人同。","时有采芝客，来自蓬山宫。"]},{"t":"琴士王彦辅","f":"曲","c":["八音各殊器，可贵在丝属。","弦歌皆雅调，清庙特于穆。","斯人久已逝，唱咏不可续。","似闻汉中叶，犹传鹿鸣曲。","旧谱今尽非，虚声以相逐。","琵琶马上啼，箜篌水中哭。","弛张异所宜，弦高哀响促。","庶子一洗之，高弹继遗躅。"]},{"t":"吴中汤孟实余闻之衍师道原同居七世矣能率正其家人庭无间言室无私藏诸舍少有不律辄晨起盛服至其寝门引咎自责必改而后止天子赐复以表孝义之门馆阁名臣皆为诗歌美之余虽未见君子中心藏之矣遂为之诗所谓不必寄元也","f":"曲","c":["麋鹿尚群聚，鸾凤自孤鶱。","请书汤氏事，愿使薄俗敦。","其人字君实，其貌肃且温。","推孝达本始，同居及诸孙。","聚食近千指，何曾异一门。","弟兄尽廉士，娣姒多淑媛。","室中无私藏，堂上绝忤言。","卖药隐东市，共知齿德尊。","佳气日充闾，五云郁屯屯。","九天降雨露，自叶将流根。","赐复以终世，举家蒙厚恩。"]},{"t":"陈允斋楼居扁曰可以","f":"曲","c":["大楼高百尺，青红半空起。","小楼二丈馀，适事亦可以。","时节会亲姻，伏腊供祭祀。","左方治杼柚，前列考图史。","览观云水宽，玩悦风日美。","玲珑豁四窗，吾心正如此。"]},{"t":"陶与权南园别业","f":"曲","c":["琼田无恶土，玉树多好枝。","鼎角匿犀者，自是名家儿。","应门有暇日，颇作佳园池。","朝临二王书，暮吟三谢诗。","花边迎小车，竹下理残棋。","宾至可命觞，亲在志无违。"]},{"t":"陶氏子竹居","f":"曲","c":["幽居少邻并，野竹绕舍生。","秀色染篇帙，疏阴洒檐楹。","物亦有奇节，人将垂令名。","须裁十二律，吹作凤凰鸣。"]},{"t":"与韩仲实九日登涵山有怀韩伯清","f":"曲","c":["凉气薄莫商，时菊委多露。","兹辰足相娱，舟楫旋且具。","往日岂复来，新人已如故。","百年几两屐，更踏涵山去。","穿空上危级，身高鸟飞处。","江天入遐眺，暝色起烟树。","始昏见横参，岁与秋俱暮。","君子殊未来，役车在中路。"]},{"t":"无云而雪时在谢氏","f":"曲","c":["白日天无云，雪花明昒昕。","僮子走相诧，个个瑶花文。","饥人尚糠覈，寒士方缊黂。","丰年望先兆，无乃为妖氛。","欲持一书札，问彼玄精君。","中情自激切，神听远不闻。"]},{"t":"闻旧馆人高斯和之丧吊其子德渊","f":"曲","c":["川谷掩灵气，门户有丧氛。","栖神托微息，变灭归无垠。","时过不再春，日昃不再晨。","诸生尚华发，何况我与君。","昔者搴芳芷，研席遗清芬。","输心结分好，无乃太悁勤。","嗷嗷霜下鸿，犹知念同群。","几日吊遗孤，哭酹青山坟。"]},{"t":"浙江观潮似介石兼呈陈守中","f":"曲","c":["朝看潮水生，暮看潮水落。","大江日东流，自绕青山郭。","长澜驾归风，秋气正萧索。","万雷鼓腾趠，百鬼凌喷薄。","蛟龙窟宅移，蓬梗共漂泊。","况尔蛙黾微，埼岸所栖托。","浩荡天地间，一气同橐籥。","吴儿踏浪游，自许平生乐。"]},{"t":"送黄少监晋卿还金华","f":"曲","c":["惟我宗人兄，早登南宫试。","当时太极赋，可使纸价贵。","文章有馀勇，一鼓作士气。","旋收成均誉，遂发兰台秘。","迎亲来远游，禄仕见初志。","悬车不及晚，重是爱日意。","桓楹树阡表，彝鼎铭祭器。","哀荣两无忝，子道兹盖备。","昔往弗可追，今归复何亟。","江皋冠盖集，潮水舟楫驶。","能无英琼瑰，持用答嘉遗。","回首望金华，草树亦增贲。"]},{"t":"寄介石索寒菊","f":"曲","c":["时菊晚逾好，金彩照微霜。","庶尔同岁寒，解后不得将。","寤寐忽有觌，道人冠帻黄。","入梦还出梦，顾影但空房。","天地生万物，淹速自其常。","甘苦亦随化，乐彼未渠央。"]},{"t":"介石遗余翁鞋歌以为谢","f":"曲","c":["衰年足趺冷，火缶不少离。","投我双青鞋，针迹匀且致。","跫然试幽步，蹈履必雅地。","出户复入门，徘徊感嘉遗。","将非尚方舄，飘飘有仙气。","岁晚动行色，远道随所至。","南北岐路多，邅回来不易。","庶将黄石书，报君圮上意。"]},{"t":"寄胡伯衡","f":"曲","c":["阳元外家儿，衡也独尔雅。","昔同丱角游，今各为老者。","蹉跎江海上，䟤跋风尘下。","馀生复几时，短发不盈把。","久思比园庐，犹将弄杯斝。","饥鸿远相呼，积雪遍中野。"]},{"t":"弟玮来奔父丧写忧四首 其一","f":"曲","c":["弟从江东来，沉痾仅能起。","恸哭我先人，旅榇在千里。","丧期岂无数，佣力方有俟。","人命终若倚，吾衰复如此。","堕泪下承睫，览镜拂铅水。"]},{"t":"弟玮来奔父丧写忧四首 其二","f":"曲","c":["昔者母教儿，过于我严君。","至今清夜中，梦想见劳勤。","深恩久未报，白发纷如耘。","扬名不及显，痛恨思遗训。"]},{"t":"弟玮来奔父丧写忧四首 其三","f":"曲","c":["孝养岂有足，促促岁月驶。","承欢顺颜色，万一有不至。","靖言念前非，良悔亦已迟。","更敢责后人，聊使后人知。"]},{"t":"弟玮来奔父丧写忧四首 其四","f":"曲","c":["去年被群偷，终岁不得宁。","讫今觊小康，大忧重相仍。","蒺藜不可据，荼蓼不可茹。","兹事未易了，兴哀欲谁语。"]},{"t":"奉呈乙十一叔父","f":"曲","c":["肮脏复肮脏，零露沾草莽。","亲癠当此时，愤惋恒独想。","孤丧寄旅榇，未知所归往。","匪人神曷依，闇室有灵响。","诸从与父同，重我心郁怏。","五茸阻长谷，寒水白漭漭。","疾忧迫衰暮，贫辛似畴曩。","夫岂无他人，相依在宗党。"]},{"t":"过小长安","f":"曲","c":["已行上河舟，初入小长安。","路逄市中儿，相邀买罗纨。","罗纨非不佳，此物生饥寒。","山中大布衣，岁晚聊独完。"]},{"t":"赋竹居 其一","f":"曲","c":["好风从东来，吹我石上竹。","取琴竹下弹，希声不成曲。","桃李正无言，世人自相逐。","繁华此何时，所贵君子独。"]},{"t":"赋竹居 其二","f":"曲","c":["残棋久未收，竹凉成小坐。","樵苏冷不爨，所设惟瓜蓏。","风吹碧云动，时有苍雪堕。","焉知人间世，赤日如焦火。"]},{"t":"赋竹居 其三","f":"曲","c":["远过幽人居，支筇立良久。","竹影落秋波，照面绿于酒。","俗士不必来，屐齿苍苔厚。","案头二王书，妙不数颜柳。"]},{"t":"赋竹居 其四","f":"曲","c":["好画不厌看，奈此风凄洌。","翠禽双飞来，翻枝落残雪。","竹间见石友，岁晚共贞节。","淡如君子交，冷面炙不热。"]},{"t":"惜花","f":"曲","c":["花开颜色好，花谢颜色衰。","颜色不可久，惜花枝尔为。","不如惜树木，树木多好枝。","君看新雨馀，郁郁生华滋。"]},{"t":"赠相士薛如鉴","f":"曲","c":["松桧角崭若，瓜瓠腹果然。","贵者自有相，畸人休怨天。","班超本燕颔，马周亦鸢肩。","苟非眼若电，便应面如田。","我昔不自知，愦愦三十年。","头颅忽潦倒，眉目徒清妍。","论心在择术，斯言心可镌。","何疑子荀氏，尝作非相篇。"]},{"t":"感兴","f":"曲","c":["松柏非不凋，其凋异常木。","故萚犹未黄，新荑生已绿。","先生贫亦甚，饥吟撼空屋。","衰谢分所甘，但使来者续。"]},{"t":"寿张南石宣慰","f":"曲","c":["留侯自人杰，功名聊复尔。","既见黄石公，更从赤松子。","神仙好楼居，逍遥远尘滓。","囊中餐玉法，于今几刀匕。","碧桃三月花，照影瑶池水。","阿母紫霞杯，睟面红光起。","西山青鸟使，书来道蕃祉。","宜尔寿千春，朱颜常韡韡。"]},{"t":"题曹云西桂根图","f":"曲","c":["何人操玉斧，夜半缘青冥。","斫去月中树，千秋伤我情。","无根亦云已，有根当复生。","但笑吴刚者，负此不义名。"]},{"t":"寄陈守中","f":"曲","c":["刁刁霜下枝，燮燮风中叶。","迢迢良夜深，恍恍佳梦接。","雅怀东里君，清心进玄业。","楼居似仙人，逍遥远嚣杂。","天辰不可攀，海水不可涉。","吾独走尘间，风雨书一箧。","手把昌阳根，谁能便衰飒。","湘也几日来，看花引杯榼。"]},{"t":"送礼绝学上人还下渚 其一","f":"曲","c":["西游五天竺，东上三神山。","相去各几许，悠悠生死关。","我欲往从之，忘世良复难。","大道固无为，此身要勿閒。","乾坤性吾德，父母形我颜。","壮志方未酬，努力更加餐。"]},{"t":"送礼绝学上人还下渚 其二","f":"曲","c":["落叶飞清霜，长飙薄林樾。","青山频梦归，夜半孤舟发。","宁无金错刀，呼酒与君别。","歘来语匆匆，径去心孑孑。","清溪今夜寒，梅花满篷雪。","相思曲未终，冻琴弦欲折。"]},{"t":"赠沈梅隐","f":"曲","c":["玉衡指幽朔，山川方涸阴。","万木尽刁脱，一德闷天心。","孰令得气先，孤花耀阳林。","此意识者希，谓易弹吾琴。"]},{"t":"哭彦实叔祖","f":"曲","c":["恭惟曾祖君，三子各才谞。","伯仲既蚤亡，宗事叔是怗。","当时师道尊，户外列宾屦。","诸生尽显庸，夫子但环堵。","几年充赋归，风雨西陵渡。","捷音久不闻，乃今得哀讣。","惊怛五内伤，苦泪堕如雨。","偭思童丱初，侍母拜膝下。","今兹三十年，吾亦丧吾母。","本支百世亲，不绝仅如缕。","恸哭复奚言，哀哉绳祖武。"]},{"t":"感事","f":"曲","c":["絺疵谏智伯，范增说项羽。","岂不怀尽忠，所事非其主。","明哲思保身，见几常远去。","毋为守污辱，白骨怨黄土。"]},{"t":"送胡伯衡归庆元","f":"曲","c":["朝看江水平，暮看江水倾。","江水朝暮流，游子东西行。","与子同自出，相依在飘零。","君归逝不复，我行乃睘睘。","上有白发亲，下有黄吻婴。","晨餐累百指，日食几无赢。","风霜所匽薄，忧患况靡宁。","旧学旋废遗，岂足希世荣。","买田临清流，筑室依近坰。","绕园莳果蔬，亲戚有合并。","此乐何渠央，此志终莫成。","勿为苦悲歌，悲歌怆人情。","艰难望骨肉，岁月如奔星。","悠悠南去云，跂踵怀先茔。"]},{"t":"感事","f":"曲","c":["堂堂美髯公，神姿凛如昨。","多财竟何为，本支遂交恶。","欲令弭纷争，此心甚精白。","人其谓我何，我思逃鬼责。"]},{"t":"大人生日","f":"曲","c":["惟我文洁公，起家二千石。","至今江左士，犹能诵遗德。","及余父祖孙，四世嗣宗嫡。","生为贫所驱，束书常旅食。","近闻甬上州，地有十亩宅。","庶几莳松菊，晚节奉娱适。","大人心坦夷，善行久已积。","眉寿定可期，我辰在箕翼。"]},{"t":"湖上醉归似吴季良","f":"曲","c":["湖上天已秋，城中汗如雨。","喧寂稍不同，炎凉亦何遽。","始知物外游，拔足风尘去。","高卧南山阿，不踏东华路。"]},{"t":"吴友之得男","f":"曲","c":["醴泉非无源，芝草非无根。","乃翁树阴德，令子生高门。","汝今为人父，汝亦有父存。","汝能念汝父，汝子复汝孙。"]},{"t":"顾德玉万竹轩 其一","f":"曲","c":["日出尘未动，清坐傍疏帘。","帘影带深竹，风漪摇四檐。","花时甘澹退，寄怀在棋奁。","举手属有念，食子乃久拈。"]},{"t":"顾德玉万竹轩 其二","f":"曲","c":["壁间棕毛拂，窗下漆棐几。","一尘飞不来，竹色净于水。","宾退日更长，清风亦时至。","兰亭脩禊辞，硬黄临茧纸。"]},{"t":"顾德玉万竹轩 其三","f":"曲","c":["白日何促促，秋灯动华屋。","所思浩无端，开轩坐幽独。","凉月出东楹，琴声隔深竹。","欲问弹者谁，童子睡正熟。"]},{"t":"顾德玉万竹轩 其四","f":"曲","c":["江晚雪初集，翠竹声珊珊。","晓超当南荣，飞舞万玉鸾。","爱此不能去，岂知双袂寒。","欲招丹渊子，写作图簇看。"]},{"t":"赵初心坐中赠中上人一元","f":"曲","c":["敲冰作砚水，题诗亦何急。","山僧亟欲去，童子庭下立。","问讯前村梅，犹带雪花湿。","惜别空踌躇，折赠不可及。"]},{"t":"春寒","f":"曲","c":["长风西北来，动荡不能宁。","尘沙乱白日，草木变秋声。","阳德久未舒，繁霜况相仍。","苦寒衣裘薄，酒且屡屡倾。"]},{"t":"湖上似濮乐閒吴季良","f":"曲","c":["湖水碧于玉，湖船深似屋。","银罂供奉酒，金缕新翻曲。","花浓春亦醉，波净云可漉。","当为故人饮，但畏白日速。"]},{"t":"自怡斋","f":"曲","c":["晏晏秋日晶，倚阑鱼乐时。","云烟生远思，水木涵清晖。","田父肯见邀，家儿可言诗。","如斯亦云足，幽偏得自怡。"]},{"t":"写愁似胡伯亮 其一","f":"曲","c":["阳元外家儿，生世何酷似。","两翁幸无虞，二母俱已矣。","青云难与期，白日非可恃。","动止见羁束，晨昏阙娱侍。","鸣雨清夜长，野蔌剪畦翠。","苦语出肺肝，屡饮成恶醉。"]},{"t":"写愁似胡伯亮 其二","f":"曲","c":["兀兀鸡在栖，惴惴狐涉水。","处身百不可，在世一何累。","平生结发妻，疾势方未止。","芝苓笼中物，倾倒已屡试。","无宁作鳏夫，儿女欲何恃。","哽咽不得言，残烛泫风泪。"]},{"t":"题松石图","f":"曲","c":["毫端水墨影，纸上松石神。","老节委地尽，怪态与时新。","写物要有似，开卷知其人。"]},{"t":"月出","f":"曲","c":["月出寒木杪，照我轩东荣。","怅然下玉琴，弹作离鸾声。","夜久强就枕，孤灯如秋萤。","纸帐不自暖，一片梅花冰。"]},{"t":"昔者","f":"曲","c":["昔者瀛洲客，侍宴宜春苑。","佳禽忽翾飞，咫尺天颜近。","内人急传呼，画师阎立本。","俯伏池水头，研吮弄丹粉。","仰视虞褚侪，愧死气欲尽。"]},{"t":"有客","f":"曲","c":["有客过阳城，亲丧极哀毁。","乞贷蒙厚资，辛苦葬薶已。","他日乃复来，感激泪如水。","愿为三年佣，报君千古意。","尔行诚独贤，吾心宁忍此。","可从诸生列，学诗作佳士。","何啻百倍功，朝夕相砻砥。","一解终不通，愧负自经死。","乃知大化中，所同唯是理。","初气各有殊，振励徒为耳。"]},{"t":"至后书怀","f":"曲","c":["月色不自暖，霜气生寒芒。","卧内无美饰，床头但菰蒋。","谁家合欢帐，四角悬香囊。","芙蓉隐绣褥，文绮双鸳鸯。","起坐独寤叹，迢迢深夜长。","梅花自清苦，乃将慕姚黄。"]},{"t":"梁邦彦王官谷见访 其一","f":"曲","c":["伯鸾不愿仕，叔度亦无官。","葛越制隐服，竹皮裁小冠。","所求年谷成，斯人获苟安。","庶有一亩宫，可以歌考槃。"]},{"t":"梁邦彦王官谷见访 其二","f":"曲","c":["蚤起理素发，良朋来合并。","拂床正书册，整襟候门衡。","无忌酷似舅，季方难为兄。","朝阳双凤凰，文彩生光荣。"]},{"t":"石门张氏园几二百年事见语溪志南石先生既宣慰河东退而家居每与宾友觞咏其中闻之里父老公之曾祖君为郡太守而归有指而詈之者阍人执以请命公曰彼安敢詈我与之酒且有以赠之责门者曰吾岂以贵势凌人哉汝不待教令而拘系之是扬吾恶名以为子孙累也逐而易之噫斯其所以嗣世益昌而此园之所以弗废与","f":"曲","c":["八月荠麦生，四月靡草死。","昌荣在一朝，衰谢阅千䙫。","德人慎所积，力善树深棋。","宁不履贵盛，终无忧患遗。","世人昧理道，但爱金玉好。","忽焉如燎毛，性命不自保。","我从石门游，乃有张氏园。","阅岁已二百，池馆似当年。"]},{"t":"大宅行","f":"曲","c":["大宅何渠渠，昔时良宴同。","当户垂碧柳，夹道种青桐。","层轩不见日，高台还避风。","鸳鸯啑华沼，鹦鹉语雕笼。","伤心玉壶缺，过眼金谷空。","蘼芜怨春绿，舜华悲夕红。","衰草卧僵石，寒雨泣故丛。","人生意气得，惆怅难再逄。"]},{"t":"留石门待内弟子经不至 其一","f":"曲","c":["乘舟驾言迈，长夜方曼曼。","苍凉物华老，趢趗年景换。","顾予远适子，庶与同馆粲。","近行乃未来，久别良足叹。"]},{"t":"留石门待内弟子经不至 其二","f":"曲","c":["飞鸟有遗音，啁鸣念故乡。","长风铩羽翮，回薄空翱翔。","顾我日衰迈，乐子年富强。","飘零岂不远，死生贵勿忘。"]},{"t":"舟中奉陪南石宣慰双陆","f":"曲","c":["达人忘势分，握槊肯相娱。","相对两新月，华星匝四隅。","朽骨如有神，归马念远途。","食子久未下，罚饮当满觚。"]},{"t":"送训道村上人游浙东","f":"曲","c":["芒鞋健如马，别我向江东。","已过云门饭，还闻雪窦钟。","青山入幽遐，碧海浮空濛。","扬帆及彼岸，更有梵王宫。"]},{"t":"镊白似胡伯亮","f":"曲","c":["夜半不能寐，晓起镊霜髭。","失手及无辜，览镜还自悲。","两目遂眵昏，当复何法施。","寄言向贤兄，老于去年时。","思归不得往，零落将谁依。","悠悠浙江水，忍此长乖离。"]},{"t":"张如㯉东斋雨诗并似其子翔南","f":"曲","c":["邀客坐清昼，两酌遂终夕。","双壶交屡退，倾欢入中臆。","捋须见诗班，举手问酒白。","不有佳友朋，何以慰孤寂。"]},{"t":"洪主敬扫月轩","f":"曲","c":["明月不可扫，客愁不可道。","亲老家益贫，长饥对萱草。","稽首玉蟾君，立身苦不早。","庶尔药长生，使母颜色好。"]},{"t":"梅花","f":"曲","c":["相见汉皋晚，相思湘水春。","若非捐佩者，定是解珠人。","根头春已动，枝面雪浑消。","称是黄金屋，寻常贮阿娇。","南枝已先暖，北枝犹苦寒。","笛中吹不尽，画里得相看。","故人不可见，梅花如故人。","相思隔明月，独吟逄早春。"]},{"t":"送妇丧归弁山","f":"曲","c":["结发念旧欢，抚心常忽忽。","馀生复何求，白日待西没。","药裹三年病，蓬颗千岁骨。","儿女远相送，悲风绕行绋。","空闺锁今雨，不见旧时月。","岂不念东归，临事有仓卒。"]},{"t":"寄呈揭曼硕","f":"曲","c":["古人不可见，即欲见今人。","兰桂各异物，臭味自相亲。","峨峨白玉堂，遥遥紫宫邻。","风云集群彦，四海望光尘。","客星入牛斗，剑气横秋旻。","能无一日雅，慰我暮江滨。"]},{"t":"赏芍药似卫立礼","f":"曲","c":["四月见红药，若与春光遇。","两人可对酌，群芳此孤注。","微风不动尘，馀熏散成雾。","谈谐遂终夕，聊用慰迟暮。"]},{"t":"钱季山方寸地","f":"曲","c":["大田亘阡陌，厚积多忧虞。","治生方寸地，种德自有馀。","忠厚为畛畦，学问乃菑畬。","书中有珍味，子孙焉得愚。"]},{"t":"多雨","f":"曲","c":["多雨问庚日，推窗看卯云。","积水连巨涨，沉烟翳初昕。","荷锄虽无力，亦知农事勤。","高居但坐嚼，宁不愧盘飧。"]},{"t":"闻蛩","f":"曲","c":["啧啧复啧啧，候虫催织作。","少妇对秋缸，泪逐灯花落。","向来陌上桑，根株尽漂泊。","綀衣恐不完，尚敢望纨帛。"]},{"t":"读唐史 其一","f":"曲","c":["汾阳国大臣，堂堂负才器。","独马不衷甲，气压天骄子。","鬼貌且蓝色，顾独畏卢杞。"]},{"t":"读唐史 其二","f":"曲","c":["刘晏工理财，国用得无乏。","凡皆属士类，吏独抱成牒。","政要在养民，其事故可法。"]},{"t":"读唐史 其三","f":"曲","c":["昔者冯瀛王，始事沙陀君。","延缘入汉周，常为将相臣。","每当革命日，必有劝进文。"]},{"t":"读唐史 其四","f":"曲","c":["元载既伏诛，胡椒八百斛。","钱圜以函方，善走固无足。","不闻古宥卮，既盈终必覆。"]},{"t":"读唐史 其五","f":"曲","c":["常闻阿荦山，窃弄梨园部。","其中有驯象，宁死终不舞。","遂与雷海青，垂名照千古。"]},{"t":"读唐史 其六","f":"曲","c":["娄公有盛德，与物澹无忤。","狄相才独雄，可用安国步。","我其举所知，不必知我举。"]},{"t":"沈德中苍筠轩","f":"曲","c":["平生我知竹，竹岂不知我。","澹然万虑空，竟日林下坐。","一一青珊瑚，时时苍雪堕。","翠羽何处来，清梦忽惊破。"]},{"t":"庄仲文梅花兜","f":"曲","c":["昔日梅花兜，今作梅花庄。","儒有一亩宫，满屋梅花香。","珠树动春色，玉林浮夜光。","悠悠岁月晚，贸贸天雨霜。","平生无俗情，结交多老苍。","独有林君复，意思可相当。"]},{"t":"东斋似沈德方德中","f":"曲","c":["日出东斋明，扶桑弄朝暾。","皓皓曙色起，湛湛夜气存。","倦客双远游，蹀足来清门。","徘徊恋光影，妙契可忘言。"]},{"t":"邀月","f":"曲","c":["团团丹华树，香绕十二阑。","徘徘不能去，乐此清夜閒。","举杯和月吞，已觉非人间。","杯空酒更酌，明月去却还。"]},{"t":"沈玉泉芳远堂","f":"曲","c":["休文有裔孙，门樾千岁阴。","盘根踞厚地，芳泽远且深。","雨露所沾溉，日月有照临。","弥久将益楙，连云起森森。"]},{"t":"雪隐山人诗为沈伯玉作","f":"曲","c":["朝云适如车，夕云忽如马。","变化方未穷，讵是无心者。","卷舒自有宜，膏泽自有时。","幽栖在林壑，或者梦见之。"]},{"t":"忆瑶山故人","f":"曲","c":["瑶山一为别，悠悠三十年。","至今清夜梦，犹在瑶山边。","美人不可见，世故来萦缠。","能无咫尺书，慰此心悁悁。"]},{"t":"访南山沈彦之采金罂子","f":"曲","c":["尘襟心不怡，驾言采药去。","木颗摘金罂，刺手不盈筥。","石齿滑行屐，齧足畏侧步。","山雨秋正深，落叶沉已腐。"]},{"t":"辛已岁将游江阴君山堕马伤腕既乃扶病而往作是诗似陈希文","f":"曲","c":["上上黄君山，瞰兹大江陲。","一展万里观，悠然千古思。","正北仰岱岳，稍西望淮沂。","计彼俯视此，小于水中坻。","朝来扶桑暾，已挂弱木枝。","江尽即入海，山行复何之。","我马虽云跌，我车犹可脂。","人世若转丸，适心苟相怡。"]},{"t":"医士马德正此山中","f":"曲","c":["乡里马少游，神仙葛稚川。","结庐此山中，手披白云篇。","药草满畦埒，松枝为屋椽。","饥食夫容砂，渴饮枸杞泉。","宁与尘事疏，勿贻俗子怜。","借问此何山，但笑终不言。"]},{"t":"送钱若虚游武当","f":"曲","c":["北方龟与蛇，列舍应天星。","阴中有伏阳，在地为水灵。","祠宫嵩岳西，高露何亭亭。","析褫走万里，香火不得宁。","阿师亟欲去，江柳犹未青。","赠子诗五言，持用叩神扃。"]},{"t":"寄呈虞伯生学士","f":"曲","c":["今代虞夫子，自是瀛洲仙。","抚编诵奇文，西顾心如悬。","我昔曾大父，盖尝治临川。","手泽幸尚存，桐宫几百年。","前贤不自誉，所望在后贤。","褒嘉作美语，声光同烂然。","寸心此区区，去雁春风前。","白云不可寄，但有白云篇。"]},{"t":"送医僧有空海","f":"曲","c":["举眼空四海，大地岂无人。","尔佛慈悯故，疾患缠其身。","橐有千金药，可回万化春。","稽首耆婆尊，永言济斯民。"]},{"t":"赠顾梅轩","f":"曲","c":["客来不问梅，但问轩中人。","尔面冷如铁，尔心独阳春。","冰霜太古操，水月平生真。","亦在尘世间，不染世间尘。"]},{"t":"惠山纪游二首 其一","f":"曲","c":["跨马北郭门，寻僧南朝寺。","青云珠树林，碧草金沙地。","危径缘磥砢，寒泉写苍翠。","星垂析木光，月堕方诸泪。","含晖白日閒，动影清风起。","解瓢贮冷冽，临流浣尘滓。"]},{"t":"惠山纪游二首 其二","f":"曲","c":["九龙发灵渊，下作梁溪水。","文采多清流，波澜有源委。","我本乘兴来，岁事亦徂只。","汲此山中绿，寄彼城居子。"]},{"t":"用吴寅甫韵似吴子善","f":"曲","c":["浮云见白日，照映玉色春。","去去重留恋，行行畏参辰。","狼子多野心，蛾眉能妒人。","振袂临清流，谁与尔同尘。"]},{"t":"白云窗","f":"曲","c":["故人庐山来，寄我山中云。","山云岂可寄，寄此意殷勤。","平生错料事，所见异所闻。","开窗拆封题，飞鸟白纷纷。","举头生惭愧，稽首云中君。","庶以自怡悦，宁当混尘氛。","提携岁月久，挂向扶桑暾。","与尔从龙去，化为五色文。"]},{"t":"语溪夜泊","f":"曲","c":["语儿溪上柳，日暮生春愁。","昔年侍阿母，曾此系行舟。","孝养苦不足，生理非故丘。","临风洒客泪，付与水东流。"]},{"t":"冷泉亭呼猿","f":"曲","c":["俯石瞰寒东，饮之不盈升。","照影忽自笑，相看面如冰。","摇摇松树枝，山猿呼欲应。","渐老筋骨疲，爱尔解飞腾。"]},{"t":"呈余峻山","f":"曲","c":["先生中朝彦，早逄圣明君。","井络降英气，奎光动星文。","束晢诗四言，蔡邕书八分。","多士起瞻慕，诸生赖濡薰。","鄙也少庸劣，力学终无闻。","意谓经品题，欲超凡马群。","师道吾岂敢，屡染成緅纁。","厚德何以报，寸心中沄沄。"]},{"t":"吴兴杂咏十六首 其一 石林精舍","f":"曲","c":["精舍青山曲，石林云气寒。","夔龙方满朝，谁不爱王官。","归人独有见，聊复此盘桓。"]},{"t":"吴兴杂咏十六首 其二 佑圣宫白玉蟾壁上留题","f":"曲","c":["仙人白玉蟾，题诗留素壁。","笔势来翩翩，矆睒不可测。","将飞蛟龙影，或是风雨迹。"]},{"t":"吴兴杂咏十六首 其三 何楷读书堂","f":"曲","c":["昔贤读书处，今为梵王宫。","世事有翻覆，人境谁能同。","唯应姓何氏，与山相始终。"]},{"t":"吴兴杂咏十六首 其四 污樽亭","f":"曲","c":["污樽几千载，长在岘山硕。","何必有杯勺，聊为饮一杯。","落叶堕西风，奈此天地秋。"]},{"t":"吴兴杂咏十六首 其五 碧澜堂","f":"曲","c":["碧澜堂下水，浪波何沄沄。","远愧六客词，有感在斯文。","回舟唱歌去，弄影前溪云。"]},{"t":"吴兴杂咏十六首 其六 白蘋亭","f":"曲","c":["城郭俯寒碧，水木摇青华。","双双翡翠羽，低拂白蘋花。","如何杨刺史，不向此为家。"]},{"t":"吴兴杂咏十六首 其七 浮玉山","f":"曲","c":["渺渺碧浪湖，中有浮玉山。","相期采兰若，佳人殊未閒。","舟楫忽已晚，乘风聊独还。"]},{"t":"吴兴杂咏十六首 其八 颜鲁公祠","f":"曲","c":["恭惟颜太师，名节天下无。","身首可异处，贞心终不渝。","客来拜祠下，岂爱干禄书。"]},{"t":"吴兴杂咏十六首 其九 墨妙亭","f":"曲","c":["古来贵书迹，莫如淳化年。","千金购遗帖，墨妙生姿妍。","谁其作亭子，宋人苏谪仙。"]},{"t":"吴兴杂咏十六首 其十 清风楼","f":"曲","c":["褰裳涉危楼，倚槛对雄州。","山横太湖口，溪出少城头。","阑干十二曲，清风如凉秋。"]},{"t":"吴兴杂咏十六首 其十一 碧岩","f":"曲","c":["携酒上碧岩，挈壶松下饮。","凭高数千尺，云水白淰淰。","六月生夜寒，山眠不成寝。"]},{"t":"吴兴杂咏十六首 其十二 蜚英塔","f":"曲","c":["孤塔倚晴霄，下瞰万顷陂。","升高欲望远，未至足已疲。","怀哉尚方舄，双凫正齐飞。"]},{"t":"吴兴杂咏十六首 其十三 白鹤庙","f":"曲","c":["越俗好巫鬼，白鹤乃有神。","庙享非一朝，山木已千春。","客行亦少憩，焉知伪与真。"]},{"t":"吴兴杂咏十六首 其十四 黄龙洞","f":"曲","c":["旱日赤如火，黄龙呼不应。","摇石动云气，听松作雨声。","怅望但空归，何以慰深情。"]},{"t":"吴兴杂咏十六首 其十五 顾渚茶","f":"曲","c":["夫槩名王渚，西山紫笋茶。","水硙生绿尘，小角装金花。","尽从天使去，供奉内人家。"]},{"t":"吴兴杂咏十六首 其十六 栖贤里","f":"曲","c":["客来栖贤里，愿斸栖贤地。","秋来多晚菘，脆美敌群饩。","聊将遗子孙，庶能知此味。"]},{"t":"题高晦叔牧松斋","f":"曲","c":["山中拾松子，种作庭中树。","亦有牧养恩，异彼牛羊竖。","结构岂在多，政为读书故。","铜炉□棐几，茧纸石砚具。","松影扫更合，松声吹不去。","坐此岁月长，当知茯苓处。"]},{"t":"章谷仲莲洲","f":"曲","c":["结屋水上居，息影洲中地。","诚为爱莲者，当知楚莲意。","凉风生绿香，旭日吐红媚。","向来无极图，玩索有深味。"]},{"t":"次韵韩明善赠竺景渊","f":"曲","c":["先生已高蹈，翰墨有遗香。","学者走四方，斯文兹滥觞。","景渊吾所亲，意思何深长。","纯纯不自衒，馀子空陆梁。","我行日已迈，岁月堕渺茫。","向来丝竹音，犹在孔子堂。","勉尔思益勤，振翮高飞翔。"]},{"t":"送仲珍弟还乡兼奉内弟陈子传","f":"曲","c":["吴淞江边秋冰生，榜人刺篙歌采菱。","古来贫贱别更苦，置酒不饮心如酲。","落日长云下平楚，孤雁决起南飞翎。","救寒几日衣上褚，原头西风吹脊令。","阿㜷倚门瘦骨立，手挥五弦多苦声。","流光一瞬二十载，风纚露沐将焉成。","汝归买田嵩水曲，小筑便可开柴扃。","他年枣下实纂纂，我亦岂惮为耕氓。","芋魁作羹饭瓜麮，充腹不在罗珍盛。","金石论交有销泐，人生急难如弟兄。"]},{"t":"鸳鸯湖上曲","f":"曲","c":["妾本鸳鸯湖上女，能弹琵琶作莺语。","与郎相见得郎欢，床头黄金用如土。","黄金用尽遂不归，妾身憔悴将何依。","可怜徘徊花上月，为郎沽酒典春衣。","春衣典却妾无怨，后夜花开无可典。","寄谢悠悠世上儿，人生虽乐有贫时。"]},{"t":"忠奴李善歌","f":"曲","c":["古有富者家暴亡，众奴同谋杀其孤。","一奴匿之负以走，财实累尔儿何辜。","孲■虽小是奴主，簿书不敢欺豪铢。","哺之朝夕乳湩流，不忍去手声呱呱。","置儿床上拜床下，奴以死奉甘劳劬。","天听不远事竟白，天子有命行赏诛。","一奴宠荣众奴戮，却从主人归故庐。","双乘青骢御史马，犹执旧礼谦若虚。","寄谢悠悠天下士，未可容易轻人奴。"]},{"t":"风泾之东有鹳鸟作巢白莲寺其雄为人所执众鹳挟他雄偶其雌弗从破巢啄鷇而去市人怜之为求故雄使复合梁邦彦作义鹳行余和之","f":"曲","c":["有鸟有鸟亡其俦，其雌栖栖方独忧。","不知何处来野雄，远挟众势刚相求。","彼雌决决不可强，巢鷇覆败无一留。","市人闻之共悽恻，为求故雄使相收。","归来哀叫声欲死，天地有情当泪流。","物有定偶性则然，此鸟何必非雎鸠。","重为周南歌窈窕，人道凋弊有是不。"]},{"t":"哲妇叹","f":"曲","c":["人家生女不必能，哲妇多事丑妇贞。","美笑已足倾人城，况复恨怒生五兵。","阳德不竞阴始凝，履霜之渐为坚冰。","天下男子唯刘伶，彼形甚醉心独醒，妇言虽善亦不听。"]},{"t":"儿曾举酒为余寿冰以喜之","f":"曲","c":["我生之初日龙?，我生之后在鹑咮。","大郎善事心弗渝，为爷举酒称翁寿。","翁颜有喜儿亦欢，花插双髦舞斑袖。","六彝共是宗庙器，宁我此郎非虎蜼。","百年门户乔木残，本根正赖枝叶茂。","我今得尔我心安，愿尔有儿昌尔后。"]},{"t":"结交行","f":"曲","c":["结交不必问古今，今人非无古人心。","古人之心淡如水，今人之心甘如醴。","淡言如水味乃真，甘言如醴能醉人。","食淡不如食甘易，所以醒人少于醉。"]},{"t":"马头者故贵人家侍儿流落钱塘谢长深有诗余和之","f":"曲","c":["谢君马头歌老孀，彼神司蚕宿在房。","合精月驷耀吐芒，衣被天下为文章。","岂有所思下土方，学施朱铅试新妆。","黄金约腕珠作珰，步摇之冠云锦裳。","凉州蒲桃紫雪浆，华堂燕坐飞琼觞。","人生富贵岂有常，朝为名花侍侯王，暮为小草委路旁。","皱面如靴不复光，空悬泉刀金错囊。","却思故步心自伤，星宫之乐乐无央。"]},{"t":"玉泉元帅示余佩刀回回氏所作也如雁翎而雪色文理可观","f":"曲","c":["将军太平得宝刀，爱之不殊古孟劳。","三尺白鹇尾雪色，引缑脱室风骚骚。","摩挲秋水生净滑，俊采犹作花门骄。","盘根错节知利器，名世何必皆豪曹。","万辟千灌奇乃见，龟文缦理纤如毛。","当时已用兔胆铁，此物或取羊头销。","传家要是公辅器，苟非其人谁得操。","藏锋不试盖有待，幸勿容易污腥臊。"]},{"t":"竹斋学士作柏图得之李好古野斋平章旧物也","f":"曲","c":["蓟丘学士神仙人，词翰挥毫有馀力。","清风披腹尽琅玕，日费尚方三斗墨。","昔年乘传向蛮邦，脩竹如云楚山夕。","却回官舸过湘中，江雨椎篷写寒碧。","远势联翩数十枚，颠倒纵横凤鸾翼。","天机到处物变尽，云影纷纷洒人黑。","想见走笔如飞龙，山木水萝俱辟易。","不辞遗迹购千金，此卷于今妙无敌。"]},{"t":"韩伯清所藏子昂双松便面","f":"曲","c":["并刀剪水一尺馀，照见亭亭两松影。","玉堂学士自写真，令我悽然发深省。","耸壑昂霄五十年，健笔如锥有锋颖。","苍髯磔怒知谁嗔，老节犹将见奇挺。","直干斜分水墨痕，樛枝乱结风霜顶。","龙鸾已化毛骨残，雷雨欲来崖谷暝。","兔丝悬蔓待茯苓，回首馀光惜俄顷。","会稽公子多苦心，收拾新诗题小景。"]},{"t":"淀山湖阻风","f":"曲","c":["吴儿牵舟背如弓，跬步咫尺登天同。","四方有路无不通，我独何为来向东。","举杯酾酒慰柁工，解后勿谓吾道穷。","改方易向矢弗庸，明发风止去必从，终我不作阮嗣宗。"]},{"t":"时雨既洽园蔬并茂","f":"曲","c":["白日有渰云萋萋，篖花乱坠眼欲迷。","鸣鸠脱裤土作泥，园蔬绕舍水出畦。","王瓜引蔓上落藜，瓠叶幡幡生瓠犀。","菘甲怒长如兰荑，中厨少妇唤阿稽。","亟取大瓮淹为齑，鱼兔不获何筌蹄，晚食足慰痴儿啼。"]},{"t":"高伯雨苕溪渔隐歌","f":"曲","c":["吾闻天目山中乃有千尺之悬泉，下赴大谷为奔川。","百里清苕净如练，云光鸟影濯濯涵漪涟。","峰峦过尽见城郭，春申剑履三千客。","当时歌扇吹香拂舞茵，此夜啼螀寒月白。","何如鸭觜滩头结屋三两椽，苕花开时鱼满船。","携书一卷篷底读，琼瑰玉佩声琅然。"]},{"t":"赠縳笔温生","f":"曲","c":["温生之笔手自縳，千金善价何凿凿。","百狐不如得一兔，可敌人间万羊鞟。","剪剔霜毫取脊尻，毛颖有传非苟作。","纵横出入腕若飞，健甚鸟骓战京索。","频年万里献玉堂，名与欧虞俱烜赫。","应从马上问葛强，谁重并刀轻鲁削。"]},{"t":"题赵仲穆山水图歌","f":"曲","c":["远山如涌波，近山如积石。","远近千万山，峥嵘起寒碧。","赤甲白盐江影空，青天芙蓉五老峰。","野桥村路独归客，耳边彷佛东林钟。","沧浪老人唱歌处，日暮停篙倚江树。","倒桃笠子渔竿头，隔水高楼访谁去。"]},{"t":"醉歌行","f":"曲","c":["千金一笑如花妾，颜色如花命如叶。","千里一日奇骨马，虽有奇骨无奇价。","明月不解长婵娟，浮云欻来能蔽天。","人生富贵矢脱弦，放手一失三千年。","彼造物者予何言，醉歌小海足叩舷。"]},{"t":"刻木吏","f":"曲","c":["刻木吏，望之如神复如鬼。","昔日犹多市人儿，于今并及良家子。","刀笔之铦，毒于蜂尾。","恶木成阴，劲草风靡。","谁其使之，民俗隳矣。","众皆趋之，吾道微矣。"]},{"t":"去马叹","f":"曲","c":["玉花铁，四蹄如踣铁，青丝络头金觼舌。","一朝名数在有司，官马人间不得骑，负我惠养犹婴儿。","朔风萧梢催上道，江北早寒无宿草。","苍头庐儿双泪垂，雕鞍锦韂当属谁。","吾闻上厩天马十二闲，尔岂不得居其间。","日食太仓一石粟，立仗不受鞭笞辱，虽我徒步心亦足。"]},{"t":"秦府旧人歌","f":"曲","c":["昔日秦王履帝位，府中旧人亦同升。","一龙五蛇各变化，一蛇失所意不平。","玄龄善谋晦善断，勇如褒鄂卫与英。","鼠辈乃卖我，我岂乏尔能。","相臣为之言，天子怜悲不自胜。","斯人自薄命，更欲争天之功为已荣。","赐官三品命始下，死骨已冷唤不应。","嗟乎哉，嗟乎哉，几年人间无客星，胡不急去归农耕。","龙姿之君好事者，焉汝不作严子陵，无名之名千载名。"]},{"t":"山水小景四幅 其一","f":"楚辞体","c":["江有水兮水有波，龙鱼帖息兮风日美和。","望青山兮如眉而蛾，抚佳木兮以婆娑。"]},{"t":"山水小景四幅 其二","f":"楚辞体","c":["山出云兮不为霖雨，江有木兮不任楣柱。","朝余东冈兮莫余南浦，时乎时兮奈何汝。"]},{"t":"山水小景四幅 其三","f":"楚辞体","c":["洞庭波兮山崨嶪，川可济兮不可涉。","木兰为舟兮桂楫，渺余怀兮风一叶。"]},{"t":"山水小景四幅 其四","f":"楚辞体","c":["山之凹兮水之汇，沙棱棱兮石礌礌。","有美一人兮如彼兰茝，思之不来兮使我心痗。"]},{"t":"题吴景良荷锸图","f":"曲","c":["倚冰为山，击石作火。","人生百年，一何琐琐。","有酒辄醉，不醉亦可。","来汝僮奴，荷锸随我。"]},{"t":"狐虎图","f":"曲","c":["狐假虎威，虎为狐使。","人欲有言，恐伤虎意。","虎实未知，狐何足忌。","使虎知之，狐其逝矣。"]},{"t":"送吴季良海运歌","f":"曲","c":["神禹作贡书惟扬，汉家亦言海陵仓。","至今岁入踰百万，连艘巨海飞龙骧。","长腰细米云子白，䆉稏犹作秋风香。","上登京庾充玉食，不与黍稷同槩量。","延陵季子世不乏，被服裤褶躬输将。","军符在佩金睒䁑，上有霹雳古篆书天章。","乾坤端倪正离坎，北斗却转天中央。","吾知贞忠对越肝胆露，蹈蹂沆?不翅如康庄。","平生故人走相送，携手踯躅心飞扬。","亟呼吴娃度美曲，无使别苦愁刚肠。","燕山之南易水上，犹是陶唐帝都古冀方。","九河故迹无复在，但见夹右碣石沦苍茫。","天下壮观有如此，大君恩重险可忘。","廷臣论功上上考，酾酒再拜中书堂。","君不闻木牛流马崎岖出剑阁，鸣声酸嘶栈道长。","何如云帆千里百里一瞬息，卧看晓日升扶桑。"]},{"t":"稚子子兰歌吊番禺君也","f":"曲","c":["月离于箕风扬沙，月离于毕雨滂沲。","星有好风有好雨，嗟尔明月可柰何。","抚灵均之遗曲，发浩浩之长歌。","岂无椒浆与桂酒，庭前草生萧艾多。","君不闻稚子子兰方得意，三闾大夫沉汨罗。","怀王入秦竟作幽忧死，不睹郑袖双青蛾。","读书千载有馀愤，恨无匣中龙泉与太阿。","朝朝暮暮阳台下，江水东流空逝波。"]},{"t":"浴兰之歌叹往事也","f":"楚辞体","c":["浴兰汤兮沐芳，思美人兮沅湘。","今日兮何日，搴萧艾兮满堂。","云之皋兮梦之渚，天沉阴兮又夜雨。","谓子都兮仳倠，曰离娄兮矇瞽。","珠有颣兮玉有瑕，心悦君兮可柰何。","忠不察兮志不雠，终自怼兮沉汨罗。","遗菰兮投黍，灵歌兮鬼舞。","驾飞軨兮龙蹻，倚惆怅兮延伫。"]},{"t":"蛇蟠石歌为濮乐閒司令作","f":"曲","c":["吾闻万物之精上浮为列星，天星之精堕地或为石。","异哉此石似蛇蟠，其故要非人所测。","我疑芒砀赤帝子，披剑斫地白蛇死。","老妪夜哭天不闻，群小连蜷化为此。","又疑愚公移山时，此物欲与山俱飞。","苍黄不及蜕皮骨，操蛇之神手脱遣。","年多物变形质在，岂有毒心犹未改。","睨之非蚺亦非巴，雪色正类蕲州花。","徂徕小松叶如发，一龙五蛇相纽结。","咫尺常疑雷雨来，寻常颇耐冰霜冽。","醉李主人初得之，举杯弹琴咏新诗。","便能雅拜亦不俗，未可遂笑元章痴。"]},{"t":"王维辋川剑石叶石林作精舍置之弁山下今为沈玉泉所得醉后求见因赋此","f":"曲","c":["有石有石美如铸，拂拭锋棱气犹怒。","何人鼓橐动雷风，剥削泥沙山骨露。","昔年曾看辋川图，此物题诗采菱渡。","桃花源里有人家，杏树坛边见渔父。","开元宰相太平日，爱是园池赏心具。","销沉紫气斗牛间，流落东西几朝暮。","石林使君先得之，万里相携若奇遇。","即今好事属君家，翠竹疏花倚阑处。","吴鸿无人扈稽死，纵是有灵飞不去。","嗟我安得力士赑屃如庚辰，一看公孙大娘浑脱舞。"]},{"t":"与黄南窗陈直卿吴江长桥晚望","f":"曲","c":["倚阑枫落吴江暮，地坼天倾百川注。","飞梁千尺虹影垂，人生南北多岐路。","古来吴越争为家，句践未足轻夫差。","鸟喙不可同富贵，范蠡亦乘浮海槎。","五湖水落三江口，西施却入鸱夷手。","我有此志非此时，且对长桥一杯酒。","始疑苍龙蜕脊骨，三十六鳞次第脱，渴欲饮川川不竭。","又似明月相离连，上弦下弦空影圆，行舟如梭月心穿。","雄藩千翼来飞汎，日看水兵教水战。","能诗忽忆谢玄晖，解道澄江净如练。"]},{"t":"观谢庄纳租为作此诗是岁免息者八千馀石","f":"曲","c":["穰穰大粒扬明珠，舸?塞川衔舳舻。","积囷如山?厚地，据案一呼走千奴。","阿戎牙筹尽相学，九九之术乃有书。","孟冬上朔简良日，府檄已报输公租。","持杯起为主人寿，天实赏尔其如予。","愿平槩量损称贷，勾稽不足庆有馀。"]},{"t":"郭索行","f":"曲","c":["轻舠刺棹渔火红，夜捉明月巨蟹宫。","有物郭索蛇鳣穴，古称败谷乃介虫。","横行岂欲遍天下，雷公在上声隆隆。","爬沙六跪心善躁，失脚已堕篝簏中。","两螯微生可荐酒，空筐宁论蚕绩功。","张翰亟上贺循舟，能不为尔思江东。","莼菜为羹鲈作鲙，风味视此将无同。","须寻玄真蟹舍子，更续蟹志如龟蒙。"]},{"t":"顾梅西东吴小隐","f":"曲","c":["昔日东吴顾文学，族大今为磐石宗。","林下幽居得隐者，小营斋庐无十弓。","会稽竹箭美如玉，奇才更出菰芦中。","卓然学道见真性，气貌穆若扬清风。","园有佳蔬胜食肉，春初早韭秋晚菘。","莼菜何惭八珍味，橘树亦疏千户封。","静观物化那有极，虎可为鼠蛇可龙。","大痴小黠竞相逐，胡不远视要其终。"]},{"t":"仲珍弟阻冰谢庄","f":"曲","c":["河水夜合冻冷生，行人欲往急打冰。","冰坚如石不可动，威棱崭露声硁硁。","船头黄帽且勿怒，速来吹火煨馀罂。","前川咫尺论万里，念尔翾飞双脊令。","后庚三日日在癸，水德不竞木始萌。","当有好风自东来，一夕为我□□□。"]},{"t":"诚上人道元树石","f":"曲","c":["江风吹树叶尽脱，交枝相缠乱如结。","箸节刻露夔一足，霜雪几年冻不折。","昨夜沙头秋水生，怒湍触石与枨争。","恐为浮槎逐海客，不见土羊成木精。"]},{"t":"衍师道原双松图","f":"曲","c":["小石如拳大如瘿，石上亭亭松树并。","谁从山阴得茧纸，幻药毫端写双影。","风雷太古见植立，冰雪平生惯凄冷。","下有茯苓千岁根，可为人间驻流景。"]},{"t":"次韵戴彦叔见寄","f":"曲","c":["人间制锦金粟尺，裁量无差较如一。","文章要是机轴同，新巧小奇何足识。","多君肯说江夏黄，剡中戴逵亦少双。","两穷相值各可笑，宁尔訾相非奇庞。","富贵不来良己巳，万事东风吹马耳。","赌棋别墅要自佳，谁能更为苍生起。","无官只作常儿遇，布衣不羡流黄案。","玉楼佳召惜芳年，金谷俊游悲故主。","夫须小笠乌纱帽，城外孤村春水绕。","碧岩直上八百级，半空飞瀑看尤好。","古来隐者非怪迂，每从此地逃侵渔。","我生百拙兔守株，操觚逐食计甚疏。","岂有大志恢雄图，家无甔石心晏如。","焦先雅爱蜗牛庐，便欲往置烧丹炉。","桑君之书悬左肘，已非昔日攀云手。","江南春色苦无多，忍见行人折官柳。","但愿飞霜九转成，与君晚岁扶衰朽。"]},{"t":"与大舟并行遇风感兴","f":"曲","c":["大帆引縆去如飞，小帆翳翳行苦迟，谁其敢争风使之。","少时风休帆力软，原头树高桅子短，前舟却输后舟远。","吁嗟世事非一端，咫尺行路易复难，人生得意莫尽欢。"]},{"t":"岁晚思亲","f":"曲","c":["寒冰凄然岁欲徂，我独何为水中居。","双目鳏鳏如钥鱼，长夜思家梦亦无。","大人耄矣日几馀，筇竹小杖不肯扶。","恒恐平地生忧虞，愿为飞梁跨连湖。","来往并置捷走奴，五日一送甘旨厨，十日一报平安书。"]},{"t":"雪中过机山明日寄周彦良彦英兄弟","f":"楚辞体","c":["雪飘飘兮洒予，风燮燮兮振衣。","水㶁㶁兮有声，冰棱棱兮在陂。","鼓独枻兮兰舟，日既晏兮莫知。","所之僮瘁?兮问予，尔所思兮为谁。","我所思兮非尔所知，山中之人兮戴逵。","岁周行兮莫只，慨星霜兮屡移。","终过门兮不入，曰古昔兮有之。"]},{"t":"送松江杨知府","f":"曲","c":["海上有马狞若獒，杨侯得之刲作肴。","仓中有鼠大如虎，杨侯得之刳作脯。","嗟嗟杨侯孔捷且武济，宽以猛爰得我所。","风雨息，海水宁，灾害弭，年谷登，五事并举政有声。","歌谣满路劳绩成，连州比邑历历相知名。","父母之心人皆有之，公独能。"]},{"t":"寄张元明时为常州务官","f":"曲","c":["踆乌西飞碧云夕，寒蛩乱啼霜月白。","青山尽处是姑苏，毗陵更在姑苏北。","故人一别音问疏，两愁无语心相忆。","三年市租输大府，能不重费微官力。","我方寄迹湖泖间，终岁不逢骑马客。","昔时梅花今又开，时独看花见颜色。"]},{"t":"新舟燕客行奉似谢德嘉伯昭叔侄","f":"曲","c":["上巽下坎木水合，大者为艑小为艓。","众宾良辰欢赏接，琵琶枨枨雷鼓叠，急管横吹指双擪。","红泉美酒倾银榼，鸾刀缕鲙鱼藿叶。","波臣川后风帖帖，喜色欢然动眉睫。","黄帽采菱相唱答，重为主人歌利涉。"]},{"t":"玉泉万户见访","f":"曲","c":["马上将军浑脱帽，马前大旗狼尾纛。","自从蛮洞凯歌回，重为兵人息凋耗。","吾与三代同斯民，礼乐百年蒙乳抱。","久知天族最多奇，不似其馀心猛暴。","虎帐秋来日日閒，散步逍遥屏呵导。","时听白发老书生，一鼓雅琴清角调。"]},{"t":"观浙省新址","f":"曲","c":["钱唐故都犹丽雄，民居百万如蚁封。","一夕熛怒赤熁空，市舍歘忽随歊风。","丞相夜下哀瘝恫，飞书走檄动帝聪。","大宽赋入振乏穷，乃恢黄堂基益隆。","斯民子来争赴功，岂弟君子汲黯同。","吴山蜿蜒若火龙，渴欲急水鳞甲红。","胡不移置山南东，远挹江上青数峰。","冈阜回合水朝宗，环拱北极当天中。"]},{"t":"余游暨阳访道士吴清逸见大龟如车轮五尾色苍黑类古铜蹒跚而行特特有声因为之赋","f":"曲","c":["惟尔大宝元龟，集虚洞玄。","吐纳精气，介虫之仙。","衡曳五尾，蹒跚而前。","皮肌鳞鳞，支节连蜷。","若倾耳以屡听，闻足音之跫然。","不用世以蕲求，固有觌于几先。","其德孔明，其心善渊。","形质已异，而神独全。","尔不自衒，人其舍旃。","持以为圣人寿，如其年如其年。"]},{"t":"樊中之鹤折其胫而死人莫之恤余独为辞瘗之","f":"曲","c":["使尔为羊，人不汝忘。","使尔为马，人不汝舍。","孰使尔为鹤，其骨荦确。","食人之食，不羊马是若。","不安尔处，将飞而翀。","忽焉跌伤，乃今畸穷。","尔鸣孔哀，尔心孔棘。","困于樊中，虽死谁惕。","瘗鹤有冢，古人之为。","神其上升，吾与尔铭之。"]},{"t":"纪梦哀容斋陈君也","f":"曲","c":["昨夜梦中逢故人，华屋凉天正潇洒。","银罂美酒雕玉觞，亦有尊前唱歌者。","馀欢未尽忽惊寤，蔌蔌寒花落灯灺。","忍将今梦梦昔梦，梦去愁来泪盈把。","西园公子多雅怀，死骨凄凉在中野。","当时苦爱椎凿声，岂思此日无遗瓦。","古来丰家无好儿，荆棘铜驼秋露下。","草间翁仲不解语，焉用鬼驺牵鬼马。"]},{"t":"余自辛亥岁馆于魏塘吴氏时义士静心先生方无恙长子彦良应门于家次子景良输力于时皆一时伟人季子季良为赘婿于外与余尤相友善岁壬申景良卒于官所归葬胥山诸孙各求分异学遂废而余乃去矣顷者不逞之徒坏其守冢之庐季良之子璋闻于官罪人斯得众称之曰能故为是诗以勉之","f":"曲","c":["天目诸峰来迤逦，又向钱唐渡江水。","伏龙骪骳行地中，东尽由拳还崛起。","想见昔日遭秦驱，太古风雷入鞭箠。","山君据地不肯前，至今乱石犹西指。","下有石龟形质具，蹂躏良田捷于鬼。","伍员挥剑迹尚存，缺齾不完神乃死。","当时结友番禺君，别墅园池此经始。","朝阳亭上醉春风，谢安曾爱东山妓。","回首光阴二十年，往事浑非山尚是。","叹息佳人曹子丹，翁仲无言荆棘里。","摇铃鼓哨旁若无，乡里小儿何敢尔。","脊令脊令飞且鸣，能事多惭伯颙氏。"]},{"t":"忆昔行","f":"曲","c":["忆昔侠家全盛日，江左数州无亚匹。","黄金横带虎作符，尽斥民居为第室。","长腰细米光照人，自给不求归老秩。","舂陵石几汝州瓷，一席万钱犹俭率。","是翁九十乃未殂，牙齿重生发如漆。","已无馀福在人间，此理分明可谙悉。","健鹘生雏尽攫拿，骄马作驹终覂逸。","寄谢悠悠世上儿，过眼繁华如电失。"]},{"t":"谢氏池上观雪","f":"曲","c":["二月春光如水冷，池上倚阑观雪影。","飘飘飒飒舞回风，颠倒瑶花落天井。","鱼吹柳絮忽销沉，却避寒澌依藻荇。","何处飞来双脊令，令我悽然起遐省。"]},{"t":"次韵陈县尹汉卿见寄","f":"曲","c":["九华山前江水长，平生故人黄绶郎。","百里犹将劳抚字，欲行不行心未忙。","与君已在杖者列，岂忆他时能醉狂。","恨无长云数百尺，一吐愤思三千行。","草间雉子毛羽短，不拟霄汉参翱翔。","题诗采石吊李白，或者一驾西飞航。"]},{"t":"用水精丸炷火灼丹田中","f":"曲","c":["仙人掌上水精丸，摘得金茎秋露颗。","亦同阳燧大蛤珠，摩挲向日出真火。","冰台作炷丹田宫，流光直射如血红。","梅花一夜孤根暖，却笑小还无近功。"]},{"t":"拟送曹世长之官柳州赌博寨","f":"曲","c":["将军曹霸有令子，躯干魁梧如北人。","辞亲再拜捧黄檄，去作柳州游徼臣。","櫜鞬已乘官驿马，顿置仍给公厨珍。","引弓之民百砦列，控扼峤海安朱垠。","伏波故事亦久矣，岂有铜柱犹嶙峋。","且当永念易播意，持酒一酹罗池神。","孤云东北望新月，山川迢遥来苦辛。","弹舌风雷语刺刺，索笑万里梅花春。","桄榔大树粉作饵，椰子酒熟甘而醇。","食膎每与华俗异，慎勿触手腥蛇鳞。","爱君貌似娄师德，故是方口又博唇。","古称容容多后福，唾面自乾可勿嗔。"]},{"t":"与宇文同知张主簿游道场山","f":"曲","c":["三月三日天气佳，县官出城早休衙。","亦有前溪宇文氏，水晶宫外看春花。","碧浪微风动浮玉，翡翠兰苕采柔绿。","笑指高人读书处，轻舟已到何山麓。","何山山头更是山，路出千岩杳霭间。","僧居蜂房开户牖，灭没紫翠飞朱丹。","川原忽满最高阁，五湖烟云一凭阑。","昔年恶虎今在否，但见丑石遗苍顽。","丽姝来往多如雨，紫绫香䙬结金缕。","佛前细语人不闻，倒坐蓝舆下山去。"]},{"t":"立春日赠仲珍弟","f":"曲","c":["阿父八十兄六十，弟亦今年五十五。","千里一家同得春，春日春盘行菜缕。","汝缘久别奉晨昏，我仍渐老怀乡土。","常时相念惜相分，此日相娱喜相睹。","劳碌馀生病后身，陶写真情醉中语。","共将卮酒拜亲前，岁岁亲前吾与汝。"]},{"t":"生日戏书","f":"曲","c":["天弧之南老星公，素发垂耳冠夫容。","青鸾引车双羽童，翩何姗姗来御风。","我生甲子旬再逢，颠倒扑漉随飞蓬。","磬折而趋跽鞠躬，神人妙颜冰雪容。","遗我松子种作松，流肪千年虎珀红，尔能得之寿乃翁。"]},{"t":"韩季博所藏青山白云图","f":"曲","c":["门外马蹄三尺尘，屋底青山看白云。","不知身世在城市，但觉爽气吹冠巾。","鸭觜滩头沙渚露，依约西陵近渔浦。","恼人归思满江东，烟树半沉天欲雨。"]},{"t":"酒歌","f":"曲","c":["酒可喜亦可嗔，醒语多忌醉语真，常恐醉语撑触人。","天上星辰何历历，人间岐路长踆踆。","既不能挥戈回白日，且当拍手歌青春。","酒固非所嗔，本亦非所喜。","作事不称情，寄怀聊复尔。","噫吁嚱，牝而黄，牡而骊，先生既醉不暇知。","苦如薏，涩如杜，先生既醉不暇顾。","颂酒之德，赞酒之功。","伟哉斯人，吾其与同。","熊经鸟申尽无益，三杯可使颜再红。","归去来，游醉乡，醉乡天地犹鸿荒。","卧看轩辕摇左角，手挟北斗?天浆。","令汝寿命百有二十岁，与物无忤永相忘。"]},{"t":"薄薄酒奉别吴季良二首 其一","f":"曲","c":["薄薄酒，可杯勺，粗粗布，宜浣濯，丑妇耐贫勤织作。","我无南阳诸葛田，赤手欲探蛟龙渊。","曲中箜篌十四弦，河水东流心惘然。","角上蜗牛且酣战，鹤胫自长凫自短。","井蛙海鳖相讥嘲，何似雕鴳俱逍遥。","八珍之味不如良友，千金之富不如佳儿。","百年一息万世痴，庞公未为无所遗。","南山有木木有枝，根如盘石不可移。"]},{"t":"薄薄酒奉别吴季良二首 其二","f":"曲","c":["薄酒味薄情不薄，丑妇貌丑心不丑。","君不见天下风流朱伯厚，车如鸡栖马如狗。","河西蒲桃紫雪浆，秦中琵琶妩媚娘。","黄金快意一日乐，奄忽百岁如风狂。","天雨未休匏叶苦，江湖水深不可渡。","豫章非?众莫辨，橀榽似檀人伐汝。","汉阴丈人抱瓮归，万事反覆非一机。","博劳东去燕西飞，毋与寸草争馀晖。"]},{"t":"题叶仲明府判竹君右丞公第二子也家于富阳","f":"曲","c":["虚廊静院连深竹，色照窗扉如水绿。","题遍琅玕节下诗，高兴满怀吟未足。","尽教梳洗出清风，客来径造亦不俗。","出门咫尺是尘间，野鸟纷纷自相逐。"]},{"t":"过无锡呈五十三舅","f":"曲","c":["晓发澄江春水绿，刺篙夜下梁溪宿。","老者今年六十三，秀眉霜雪颜如玉。","大郎挟策青鸟市，小郎恂恂侍巾襆。","就中中郎绝秀殊，耽书动是千过读。","一门传恭复传孝，如此穷饿心亦足。","舅甥情爱久更亲，竟夕寒灯共华屋。","唤奴呼酒出羊淹，重说生涯乱心曲。"]},{"t":"即事","f":"曲","c":["苍头小奚得马刍，黄吻稚儿看鱼罛。","白发老人教农书，客来手把河洛书，话到混沌开天初。"]},{"t":"日出柳树东哀刘先生也先生字环翁登进士第授建德录事卒于都下","f":"曲","c":["日出柳树东，日没柳树西。","朝朝暮暮出复没，柳叶黄落半为泥。","郁华仙人驾六螭，急若弩矢谁能齐。","夸父逐之道暍死，跬步万里生蒺藜。","千载同一朝，白发如霜荑。","奈何性命不自理，只思骑马听朝鸡。"]},{"t":"送韩与玉入京求其师张仲举先生","f":"曲","c":["君家兄弟森群玉，数兼八韩仍两之。","复有一人更才敏，将往京域求其师。","其师为谁子张氏，曲颏美准秀且颀。","鸡栖昂昂立孤鹤，羽翼已遂冲天飞。","昔年助教国子学，横经气夺千皋比。","顷日还当大述作，并录三史追前徽。","使者旁搜异书出，天下学士来委蛇。","春秋用例如用律，游夏犹将赞一辞。","直书无愧董狐笔，上与日月争光辉。","子今行矣快先睹，涉阅定有新闻知。","赤华之驹不受鞭，顾影独立长鸣悲。","经途九轨奇骨见，渠忍局促盐车为。","祗疑慈母手中线，密缝政恐迟迟归。","文章有神国有造，赠子脱颖双毛锥。","好音早寄南来雁，无使淄尘污素衣。","梅花后夜琴曲苦，满天明月照相思。"]},{"t":"赠制笔沈生","f":"曲","c":["月中仙人白兔公，缟衣翩然乘玉虹。","遗我利器五色光，将使奏赋蓬莱宫。","江淹老去才思劣，夜郎归来亦华发。","愿乞瑶池不死方，须得玄霜和紫雪。","剥啄叩门秋梦回，有客真为黄香来。","坐中顿见两毛颖，脱帽露顶美且䰄。","君不闻朔土贵人执笏思对事，仓卒墨丸磨盾鼻。","何曾望见㕙与䨲，马上柳条能作字。","后来雪庵松雪俱善书，始爱都人张生黄鼠须。","安知沈郎晚出笔更好，犹及馆阁供欧虞。","拔奇取俊锋锷见，双兔健似生于菟。","用之不啻仗手檛，颠倒纵横随所如。"]},{"t":"种德堂诗","f":"曲","c":["树木犹为人所爱，况尔宗盟磐石大。","条梢之末苟勿残，可使亭亭似车盖。","枝叶能承雨露恩，乃今流被及本根。","一门青紫什七八，虽贵弗陵尊行尊。","保家要在全和气，和气致祥乖气异。","云仍百体同一身，恒使匀通有生意。","富贵浮生何敢期，长长幼幼咸在斯。","肯道吾儿幼衰替，煦妪愿如今日为。","昔之祖者今之祢，推尔所爱达尔始。","如木有根种厥德，尧舜之道孝弟而已矣。"]},{"t":"碧澜侍儿曲","f":"曲","c":["感之以诚感必深，应之以真应必捷。","真诚一合两弗离，听我长歌碧澜妾。","碧澜亦是诸王孙，世殊事异老且贫。","少陵尚爱燕玉暖，况是当时真贵人。","春衣典尽春寒峭，二妾朱颜正姝好。","忍将罗带拆同心，懊恨浮生头白早。","珠钿翠靥幸仅存，此时犹及嫁夫君。","十二楼头燕子去，挥手不用留仙裙。","去妾相悲两相约，既去犹烦送肴酌。","主君讵忍覆弃之，见此翻令情绪恶。","一心专，天得知，忍著主衣还事谁。","遂携衾襆与俱来，后君死者当为尼。","碧澜堂下双溪水，使客往来岂知此。","不愿新欢恋旧恩，千万人中两人耳。"]},{"t":"刘子舆清啸轩","f":"曲","c":["大哉扶舆，动应有机，律吕风云。","黄钟之宫，发乎自然，为声气君。","其在我人，呵嘘吸呼，节族以分。","啸乎啸乎，何浊何清，惟心所存。","力出尔手，以挤则危，以掖则安。","气出尔口，以吹则寒，以喣则温。","民各有趋，狂者如籍，壮者如琨。","嗟我怀人，愤懑既舒，亦已忘言。","冥玄洞虚，不可以名，以名斯轩。"]},{"t":"一姓三氏诗","f":"曲","c":["彼种树者，更枝易叶。","以彼成此，实相应接。","载息载滋，两殊一合。","天时既从，物亦允协。","本本支支，纷其丛沓。","初气永存，至纯不杂。"]},{"t":"伯衡北上余在琏市作此诗以送之不及","f":"曲","c":["姨氏之子平生亲，忆昨书来道相别。","青徐大小郡邑残，却走梁园向京阙。","五河高原车斗风，鲁缟齐纨吹欲裂。","读书岂是为一官，倒著狐裘拥飞雪。","重游都市十年馀，须得青袍慰华发。","日近蓬莱云气佳，冰解滹沱水声活。","羊酪甘肥马酒醲，土锉无烟石煤热。","金错披囊罄一欢，橐笔縢觚待明发。","便令南斗避文星，归插宫花醉吴月。"]},{"t":"龙头之西有伏龙山首枕巨海上有古寺云岚之气尝蒸蒸然如黄梅时唐会昌中诏毁天下僧寺寺僧作诗云云中有寺不容住天下无家何处归有旨得不毁癸酉岁余与族叔族弟及戴彦季同游获观先祖遗墨既暮余与族弟先归山半值大雷雨山上晴朗如故作诗以纪其事云","f":"曲","c":["青山如龙行且伏，渴欲饮海海不足。","轻衫短屩小筇枝，独上龙头叩龙腹。","龙腹空洞声豅豅，岂有神仓闭神粟。","楝花风起鯼鱼来，远望渔艘似浮鹜。","痛思我祖伯丰氏，遗墨宛然三过读。","无食无家走千里，尚赖馀休守觚牍。","瓜瓞子母相钩带，断蔓残根仅能续。","徘徊瞻眺不胜情，贫贱何由复邦族。","忽从岩半黑云生，归去惊雷撼崖谷。","相望咫尺异阴晴，众客山椒我山麓。"]},{"t":"某甫者章氏之庶孽子也所出微不得与众兄弟齿治田庐供衣食比分财得黄金盘杆一其从父弟俊甫方脩青龙镇学一日持以造之曰我为农无用此吾家二先生死无后愿鬻此置祠学宫之侧买田收其租入春秋二时用少牢具祀之以徼福于先圣先贤慰吾父与伯父师弟子之心冥冥之中其为我经营之余与闻斯言时至元后癸未岁也每思其人故作诗以寄之","f":"曲","c":["章氏孽子操心危，少曰已爱躬芸芓。","夫耕于前妇后馌，饮酒安用黄金卮。","不向尊前赏歌笑，买田独置先生祠。","讵忍若敖无噍类，工执艺事犹有师。","昔闻此语心为喜，至今思之不能已。","到处真同说项斯，遑恤他人恶闻此。","当时师说诒李蟠，弃置床头如故纸。","乃今面目被生憎，况肯兴怀尊死鬼。"]},{"t":"伯清兄弟在者三人次仲实又次季博有练溪别业连云庄弗肯分异户门应酬衣食用费宾客燕会岁一人递收其田租以掌之为计帐以相交付同堂异室内外无间言于兹有年矣是亦保家之善道也不然则力分而用广日且不给况能久而弗坠哉是宜诗伯清即韩分石","f":"曲","c":["会稽公子谁与俦，埙篪并和声相求。","户门多事须应酬，茧丝谷粟岁递收。","公尔忘私无怨尤，娣娣姒姒俱淑柔。","醪醴洁治蘋藻羞，岁时祭飨礼数优。","譬如风波同一舟，戚则共戚休亦休。","彼哉何人此弗犹，兄弟生分如死雠。","上健下险森戈矛，黄金用尽身为囚。","令我感叹泪欲流，人无远虑多近忧。"]},{"t":"冬至日","f":"曲","c":["大哉元气何冲融，周流六虚相始终。","为阴为阳本非二，政在往来升降中。","去年阳生阴已极，今年阴消阳复息。","君子有道喜可知，手把梅花看三易。"]},{"t":"西郊醉归似陈汉卿","f":"曲","c":["人间此客不可孤，况此翕忽岁欲徂。","吴姬双歌送美酒，半醉不醉娇相扶。","踏歌携手寻归路，行云忽送巫山雨。","却上溪边舴艋舟，舞衣湿透黄金缕。","短棹轻桡不相及，依约中流闻笑语。","归来庭院已黄昏，流水落花深闭门。","最思一事尤可怪，笠子忘却溪南村。","梦回酒醒不复记，清晓野夫来叩阍。"]},{"t":"藏钩似陈汉卿","f":"曲","c":["世故纷集如猬毛，今我不乐年将慆。","汉家钩弋作隐戏，聊足与客娱佳宵。","绿酒荡漾白银瓮，红烛照耀黄金幖。","明籹列映左右侍，大宾坐压东西曹。","平生刎颈托交契，此日意气争分毫。","老拳攘袂坚莫取，钩神瞪目不敢语。","搏兔壮士声若雷，失马将军面如土。","忍将他日严毅颜，涴墨涂鸦上眉宇。"]},{"t":"馀姚吴季章松斋图","f":"曲","c":["四明山中木千章，上有松树生高冈。","不与朴樕同翳荒，雨露飘洒云之阳。","鹅溪大绢尺度方，写貌形似分毫芒。","非龙非螭牙角狞，开卷白日风雷生。","之子秀骨须眉苍，与松为游三十霜。","小结茅屋松阴凉，采松之花餐松肪。","弹琴诵诗送流光，人生有情苦参商。","白水满地天茫茫，安得送我置尔旁。","脱落世故遗纷庞，乐与寿命如松长。"]},{"t":"伤春曲","f":"曲","c":["鸳鸯湖边花满蹊，鸳鸯湖外草萋萋。","春风醉人骄马嘶，玉花连钱锦障泥。","绣罗为襦金络缇，鲜卑小带镂文犀。","哀哉王孙归路迷，红娃翠压愁空闺。","昔时歌莺今不啼，杨花堕泪章台西。"]},{"t":"寄李坦之","f":"曲","c":["神仙中人不可招，薄言思之我心劳。","霞裾远曳风飘飘，照影独立江之皋。","岂无囊中金错刀，安得携手与游遨。","玉雁银筝紫□□，吴娃双歌送春醪。","大江东流日滔滔，江上春风吹碧桃，花飞万点正魂销。"]},{"t":"寄钱竹深","f":"曲","c":["西方美人隔秋水，优昙花开白云里。","白云无事长悠悠，美人不来我心忧。","金井银床露如沐，玉琴夜罢相思曲。","麝煤鼠尾生暗香，吴笺染恨春波绿。","织乌西飞何日还，赪桐始花亦已残。","人生有情歌欲绝，明朝览镜凋朱颜。"]},{"t":"辛未七月廿三日大雨","f":"曲","c":["孟秋之月月在毕，雨气斗集云深黳。","悬河翻空海水立，万瓦千霤如奔溪。","向来高原变洿泽，巨浪上蹴天为低。","三吴良田入井底，菜茹岂复如畛畦。","室庐藩溷尽漂没，存者历落犹鸡栖。","男儿性命不自保，往往中路遗嫛㜷。","书生有情泪沾臆，落日黤黯秋云西。"]},{"t":"梅花庵为吴仲圭作","f":"曲","c":["函三一气初未分，包括万象为阳春。","亦如孤根抱独暖，不与桃李同光尘。","吁嗟此意知者少，我欲往问庵中人。","高官不如士白贲，厚富不如农赤贫。","结茅为椒小于笠，翕翕鼻观通机神。","眼中见花不见我，我身己与花为身。"]},{"t":"次韵王达之园池假山并似钱春野","f":"曲","c":["海上诸峰皆绝奇，其高无颠下无涯。","一峰飞来在平地，小小亦足同幽期。","近结斋庐处其下，十里平川见多稼。","客来政有酒盈尊，我生不作悠悠者。","突兀眼底多伟观，如虎如貔气桓桓。","或窈而深如洞穴，或峙而立如冈峦。","如积钱色万钧重，如鸾鹄停欲飞动。","人间此景不可孤，风月佳时与君共。","偎花倚竹相鲜新，寒士亦各忘其贫。","胸中丘壑故不俗，元章石交平生亲。","世变纷纷参复伍，岁晚相看吾与汝。"]},{"t":"次韵贾玄英烈女祠祠在嵊县青枫岭至元丙子天台王氏妇被掠至此齧指血题诗石上云君王无道妾当灾弃女抛男逐马来夫面不知何日见妾身当是几时回伺兵士少间投崖下而死","f":"曲","c":["女郎号天杀气黑，题诗齧指生血滴。","天白赤城山为低，一掷万仞惊魂飞。","将军讵忍驱迫为，夫君不见我心悲。","国破家亡两依依，人命几何花脱枝。","不学明妃辞汉宠，犹使胡儿拜青冢。","流光一去若箭弦，安用马上啼婵娟。","语言侏离不可解，妾有一身无二天。","节不可移头可碎，口血未乾身已坠。","馀生含笑入九泉，不向人间偶殊配。","天地阴阳有消息，终始一心如铁石。","至今积水閟幽灵，呜咽疑闻髑髅泣。"]},{"t":"海大船","f":"曲","c":["太仓龙骧万斛船，欲动不动艇子牵。","沙江水浅潮易落，咫尺见海去莫前。","艇子勿誇尔能事，士生未遇亦如此。","须臾水深风力强，大船却将小艇行。"]},{"t":"采枸杞子作茶饼子","f":"曲","c":["流水河边见碧树，上有万颗珊瑚珠。","此疑仙人不死药，黄鹄衔子来方壶。","露犹未晞手自采，和以玉粉溲云腴。","卧听松风响四壁，未老更读千车书。"]},{"t":"穿石松歌为叶秀轩总管作","f":"曲","c":["阖闾古城城北东，昆山迤逦盘苍龙。","天星之精下融结，其中有石皆玲珑。","山农穿山若鲮鲤，雄椎怒击雷光起。","木精土性莫敢私，蚁垤蜂窠差足拟。","三吴主人欣得之，保抱护惜犹婴儿。","剔抉泥沙出奇骨，洗濯烟雾生神姿。","建昌花瓷培宿土，徂徕稚松沐新雨。","却穿月窦出云凹，山鬼髑髅毛发竖。","题书寄远情可知，结交岁晚心勿移。","一卷自有丘壑意，百折不受冰霜欺。","终朝坐对兀若痴，茯苓琥珀生有时。"]},{"t":"苦热行","f":"曲","c":["十日不雨草树焦，一月不雨川源竭。","酷吏作威何可当，大地流熺赤于血。","嗟我有情空自伤，会擒女魃出神潢。","手挽悬河作甘澍，坐使大地生清凉。"]},{"t":"邹一初提点三清阁","f":"曲","c":["杰哉高阁开神区，此地何必非玄都。","天上玉京十二楼，飞来人间作画图。","栾栌交加虎兽伏，甍宇轩翥龙鸾舒。","上方自与三境接，星光历历种白榆。","晨朝焚香礼碧落，仙风半空闻佩琚。","此生尘网如可脱，愿为清歌随步虚。"]},{"t":"天星湖上歌似吴泰然","f":"曲","c":["秀州孤城悬斗口，中有湖水藏天星。","龙飞已去迹犹在，灵宫故是白玉京。","题诗欲寄羡门子，问讯或过茅初成。","交梨火枣如可得，与尔相见夫容城。"]},{"t":"郑彦昭书巢","f":"曲","c":["郑生结屋名书巢，岂欲巢居似巢父。","风南枝北两相忘，焉用缪绸开牖户。","我闻在昔巢父时，大道何曾立言语。","只从书契造文字，后来作者多如雨。","生今所藏竟何书，吾欲沧浪濯缨去。","尽令无用束高阁，坐使民风返淳古。"]},{"t":"濮乐閒得唐雷霄琴黄南窗鼓之","f":"曲","c":["霹雳昼下乖龙升，峄阳孤桐才具成。","大唐雷霄与斲削，木精咋舌山鬼惊。","漆光拂拭净如水，蛇跗欲走不得行。","主人爱琴仍爱客，层轩白月秋夜清。","请君为我尽意弹，我亦为君倾耳听。","上弦洋洋和且平，下弦琅然如叩冰。","回头始疑崩石裂，泛指忽作蜚鸿轻。","铜盘乱泣珠琲落，铁挝碎击珊瑚鸣。","江山清空草木动，律吕应会风云生。","挥杯弄影喜欲舞，主客尔汝俱忘形。","人生交契如此酒，子期知音复知声。"]},{"t":"似胡伯可","f":"曲","c":["人生百年如置棋，东西南北何多岐。","白云自是山中物，风雨一出归无期。","我居鸳湖上，子在龙江湄。","能无咫尺书，慰此深相思。","长干缘河小于带，积水满地天光垂。","沧波老树沉欲没，荒郊冷落如秋时。","小家流逃大屋走，五种不入民情悲。","思君不见心欲折，背人白鹭双飞飞。"]},{"t":"送任子昭北上","f":"曲","c":["江南二月柳如缫，欲折未折风骚骚。","天上神京春色好，兰台玉堂多俊髦。","龙江公子少年日，乃翁携之与游遨。","翰墨之馀及丹青，譬彼鲁削非凡刀。","胡为历碌风尘下，与世俯仰犹桔槔。","未必屠龙不及豨，要是钓鱼须钓鳌。","亟亟上书自荐达，一刺民瘼针如毛。"]},{"t":"同深甫万户前科赏樱桃","f":"曲","c":["将军黄金作佩符，霹雳古篆雕天书。","上有赤赤三明珠，卧护千里坚无虞。","重为王孙开酒壶，溪鲫银丝鲙新鱼。","莼龟青小滑可呼，樱桃结子红珊瑚。","吴姬能歌花不如，坐拥翠袖飞琼觚，人生百岁多欢娱。"]},{"t":"与张叔方","f":"曲","c":["去年送君作巡官，双悬雕弧夹马鞍。","今年巡官出迎客，吠犬不闻山月白。","山人畏之若乳虎，妖狐髑髅不敢舞。","㹠阱鸡埘一万家，谁子强梁能跋扈。","君不见南台贵臣急如火，櫜鞬磬折趋道左。","州司尽避供给难，君独从容无不可。","名驹千里毛骨奇，雷霆破山亦霁威。","人生才美有如此，岂可沉埋百寮底，明朝雕鹗西风起。"]},{"t":"赠飞星学古仙","f":"曲","c":["学古仙，双瞳如岩下电，矆睒龙光碧花眩。","乱摘星辰掌上飞，惊动当时出奇变。","扁舟适从何处来，湖上鸳鸯乍相见。","袖间小轴锦作幖，欲钓珊瑚入诗卷。","梅花一笑领略新，笔底春回冰雪面。","脱尔身上六铢衣，试我囊中五色线。","昔如羁鹤在樊笼，今似韝鹰解绦旋。","刮目他年看阿蒙，收拾黄金如土贱。"]},{"t":"去矣行","f":"曲","c":["使我饮酒不如长鲸，使我食肉不如猛虎。","昨夜雪深人未归，明日冰开客当去。","念尔公家急急符，白水无边走何所。","从闻海上有神仙，上界于今亦官府。","君不见东墅老人粟万钟，金钥牙筹弃如土。","秪有凄凉鬼绿珠，怨魂相从泣寒雨。"]},{"t":"赠永上人","f":"曲","c":["大休和尚少年日，尽遗俗缘甘独孤。","人间纷纷臭如帤，此身不可一日居。","黄金袅蹄明月珠，美人如花绣裆襦。","收拾众有归元无，不忍头颅生发须。","即以宅舍为庵庐，袈裟折那衣五铢。","麻鞋蒲龛坐结趺，口中波罗天竺书，高蹈万古隘九区。","绕屋青青种春蔬，焉能食肉更食鱼。","优昙花开满前除，空色两忘心澹如。"]},{"t":"江南稻　至元六年四月上海姚胜一等作閧","f":"曲","c":["江南稻，雪色白可喜。","去年八月天雨多，戢戢禾头尽生耳。","里正急公租，饥人若羸鬼。","海獠大无知，毒螫肆蛇虺。","军府上变羽檄飞，白日森然五兵起。","鼓钲动地火赩天，性命鸿毛同一燬。","古者反侧加天诛，歼厥渠魁固常理。","卖剑可牛刀可犊，不忍农夫亦遭此。"]},{"t":"将进酒","f":"曲","c":["君不见玉台明月镜，朝朝拂拭生光辉。","上有双飞金鹊影，识我少年红泽时。","山中小草无远志，流景歘忽如猋驰。","向来鬒发似鸦羽，此日春蚕吐白丝。","所以花前月下一壶酒，古人痛饮无复疑。"]},{"t":"泽农","f":"曲","c":["泽农结屋如鸡栖，舍中筑塍为畛畦。","春来无地生青草，况有菜茹供朝齑。","劝农使者出行水，对此不忍加鞭箠。","田中生鱼鱼尽肥，屋底瘦人扶不起。","先生闭门听雨声，为尔惆怅伤余情。","君不见纥干山头冻杀雀，何不飞去生处乐。"]},{"t":"庚辰四月廿日赴谢氏馆吴季良携酒为别","f":"曲","c":["东里先生乌角巾，薄游吴中三十春。","闻言不如祁孔宾，见道多惭程伯淳。","强聒自谓愚而神，胶胶肫肫不可循。","故交零落参与辰，独有一人长若新。","鸒斯之党何频频，愿逢新人如故人。"]},{"t":"凤凰山","f":"曲","c":["九山联延何郁苍，中有一山如凤凰。","凤凰不来名独好，远势似欲高飞翔。","梧桐有支竹有实，玉水侧出输天浆。","饥食渴饮无不可，何独苦爱鸣朝阳。"]},{"t":"淀山寺","f":"曲","c":["何年飞来湖上峰，中有石穴藏蛟龙。","山僧留客共清夜，竹炉怒吼松涛风。","忽疑坐我天竺下，眉间秀色浮葱茏。","借尔摩尼如意珠，听师波罗谈苦空。","与开心孔见真性，随方应现无不从。"]},{"t":"夏日泛舟","f":"曲","c":["江边青蘋风欲秋，江上白云如水流。","人间炎热不可处，驾言出游写我忧。","乌匼小巾一角垫，黄葛短袂凉飕飕。","白鸥飞来复飞去，卧听横竹商声讴。"]},{"t":"范叔豹苕溪草堂歌","f":"曲","c":["苕之水，向东流，君家草堂溪水头。","一室小于溪上舟，清风满屋长如秋。","甑中生尘鱼在釜，终日哦诗摇两股。","君不见杜陵草堂花满川，将军立马驻江干。","天吴紫凤补短褐，安用行庖洗玉盘。","良无广厦千万间，乃欲天下寒士俱欢颜。"]},{"t":"赵仲穆山水图歌","f":"楚辞体","c":["山有麓兮水有麋，石礌礌兮彼渔之。","矶水有麋兮山有麓，树翳翳兮彼樵之。","谷波极目兮双帆暮飞，我怀伊人兮渺不知其所之。","采采兰若兮充尔佩袆，弁之阳苕之浒兮来吾与归。"]},{"t":"期戴彦季不至","f":"曲","c":["众星荧荧不如月，五金铮铮不如铁。","剡溪公子来何迟，铁为灵金人不知。","君看针头小于刺，摩挲生涩无光辉。","大哉天地共消息，子北午南分坎离。"]},{"t":"双松图为程似道作","f":"曲","c":["双松挺然，徂徕之巅。","历冰霜而不凋，泽雨露而不妍。","尔植尔茂，惟贞惟坚。","用以为君子寿，如其年如其年。"]},{"t":"画鲤","f":"曲","c":["以为鱼耶，鳞甲已具。","以为龙耶，头角未露。","时至则化，厥施斯溥。","蜕骨天渊，苍生霖雨。"]},{"t":"黄南窗小像","f":"楚辞体","c":["著乌匼之短帽，曳碧绡之轻裾。","若丹丘之孤鹤，骨既清而亦癯。","嗟尔童子，抱琴焉如。","日月不可与留，归来兮乐吾初。"]},{"t":"吴瑩之小像","f":"曲","c":["骨虽清而不枯，貌虽丰而不腴。","有田与庐，诵诗读书，恂恂乎美且都。"]},{"t":"吴仲圭画松","f":"曲","c":["以尔为楹，其直不可以中绳。","以尔为梠，其曲不可以中矩。","一丘一壑，多历年所。","白摧朽骨，太阴雷雨。"]},{"t":"吴景良农庆堂诗","f":"曲","c":["维扬禹疆，厥壤维沃。","尔服尔耕，贻我嘉谷。","翼翼冷风，自南自东。","侯顺侯?，岁聿屡丰。","有稻有稌，有?有穱。","我庾既崇，如山斯岳。","先民是遗，匪予是能。","擪籥吹诗，用荐厥声。","厥声洋洋，式歌且咏。","锡庆自农，畴敢弗敬。"]},{"t":"寄吴季良","f":"楚辞体","c":["兰有馥兮，芷有芳。","我怀伊人兮，惟吴之良。","文武之道兮，一弛一张。","力有所俟兮，用有所藏。","机不可以豫谋兮，变不可以豫量。","庶君子之明亮兮，感余心兮伥伥。"]},{"t":"故建昌州判岳德敏哀辞","f":"楚辞体","c":["眷碧山之幽栖兮，驾吾舟以遄迈。","升其堂不见其人兮，抚遗孤以增慨。","览芳岁其犹未艾兮，何佳木之先瘁。","嗟浮生之翕忽兮，若奔马之历块。","舍昭晰之茂旦兮，即永夕之昧昧。","三星奄其西没兮，孤参横其谁待。","怀馆谷于畴曩兮，辰历兹其三亥。","感余情之不能忘兮，悼良会之莫再。","吊明月于中扃兮，沥觞酒以再拜。","杂椒兰以为粻兮，又荐之以芳茝。","招游魂于鄂之渚兮，莫蛟龙之为害。","狐首丘其亦已兮，羌虽死而弗悔。"]},{"t":"别夹谷知事可与","f":"曲","c":["我爱杨子江心百鍊镜，明于月，冷于水，揭之可以照天地。","我爱丰城土中三尺剑，气如云，质如银，佩之可以服鬼神。","尚不如兰陵故人夹谷氏，大雅愔愔古君子。","韬光自晦常有馀，藏锋不试终为美。","眉间有色清而温，玉佩琼琚照秋水。","我有朱弦白雪知者希。","一曲遂为相识始。"]},{"t":"堂堂歌","f":"曲","c":["君不见车如流水马如龙，大道长驱耳生风。","床头黄金借颜色，快意正在一日中。","又不见车如鸡栖马如狗，侧足旁趋面生垢。","投人不遇刺欲漫，失意宁论百年后。","凫胫自短鹤自长，颠倒万事未可量。","西来江水东流去，白日竟是为谁忙。","且当开尊酌美酒，起舞顿足歌堂堂。"]},{"t":"与陈众仲提举","f":"曲","c":["吾闻泉南山水远更奇，三苏不得专蛾眉。","天海云风发胸臆，波涛万丈倾雄辞。","越从江汉下南纪，却入箕尾乘东维。","十年依光日月角，一官遂作文章师。","平生学问龟五总，小叩大撞无不知。","东海书生双井客，思见君子瞻光仪。","君不闻龙泉干将自神物，铁花生涩埋尘黳。","宁无华山赤土为我发光彩，一使变化凌空飞。"]},{"t":"送张叔方湘潭州税务大使","f":"楚辞体","c":["使君足下远游履，茇涉湘潭数千里。","江南柳色共依依，亲老家贫须禄仕。","昔年裤褶作巡官，矢箙弓櫜悬豹尾。","于今九九学算术，却执牙筹筦州市。","炎洲蜑人卉为服，西域贾胡珠作珥。","巴賨奇货积如山，贱者翠毛兼象齿。","千万人中生俊杰，识时所务非俗士。","与民尽用一分宽，粗给官常斯可矣。","君家五世皆达官，节槩两朝无比儗。","况尔诸孙有祖风，为国理财聊小试。","扬子江头春雨深，杯行未尽离歌起。","安得相从到楚乡，澧有兰兮沅有芷。"]},{"t":"竹鸡语","f":"曲","c":["泥滑滑，江头路。","雨萧萧，君莫去。","不辞路滑马行迟，恐君衣裳污泥土。"]},{"t":"赠相士王云?","f":"曲","c":["君不见秦时照胆镜，光辉团团似明月。","明月自缺还自圆，此镜一失三千年。","我疑神物犹在此，飞入云?眉睫里。","镜不解语君能言，天机到处妙不传。","富贵功名顾盻间，可使见者挥金泉。"]},{"t":"题钱思复小像","f":"曲","c":["尔气之充，尔色之愉。","博衿长裾，而拱而趋。","雍雍于于，山泽之臞。","是所谓温润，而栗者欤。"]},{"t":"壶中一字至十字","f":"曲","c":["翁。","壶中。","无不容。","天地鸿濛。","其乐也融融。","一室烧丹灶红。","见松下青衣羽童。","是何年竹枝化为龙。","碧桃花下无日不春风。","我欲访山阴旧隐与参同。"]},{"t":"僧溥雨?赞","f":"曲","c":["充然其气之濡也，凝然其形之臞也。","缤缤乎其雨华也，矻矻乎其?居也。","遍满六虚不离一区，非有而有非无而无。","卓卓乎，西方圣人之徒欤。"]},{"t":"春晚书怀四声体","f":"曲","c":["春晚翠阁，朱户绣箔。","风起昼寂，红雨乱落。","歌枕梦熟，啼鸟唤客。","流景电激，今岂复昨。","尊酒对客，浮以大白。","余有暇日，聊与共乐。"]},{"t":"阿剌吉","f":"曲","c":["阿剌吉，酒之英，清如井泉花，白于寒露浆。","一酌咙胡生刺芒。","再酌肝肾犹沃汤。","三酌颠倒相扶将。","身如瓠壶水中央。","天地日月为奔忙。","经宿不解大苍黄。","阿剌吉，何可当。"]},{"t":"古尊彝歌为濮乐閒作","f":"楚辞体","c":["神物可使厌百祥，左尊右彝相颉颃。","云雷古篆为文章，饕餮异兽头角张。","丹砂空青金玉相，星彩错落半赤苍。","摩挲犹作黄流香，稽首再拜登斯堂。","手援北斗酌桂浆，愿君饮此寿而康。","千古既往万古长，于胥乐兮乐无央。"]},{"t":"悲歌行","f":"曲","c":["七月龙火正西流，卧看玉宇悬清秋。","三辰旋转不得息，万事反覆良悠悠。","川原尽为虎豹穴，风雨常隔凤麟洲。","君不见愚夫凭河去不返，寡妻遗妾怨箜篌。"]},{"t":"海水竭","f":"曲","c":["海水竭，海人熬波泪成血。","卤花凝白雪不如，高廪露积万有馀。","征商不行榷法坏，使者分司来趣卖。","农家食咸苦不多，盐乎盐乎奈尔何。"]},{"t":"观打春","f":"曲","c":["土牛送寒赤于火，乌衣芒儿立牛左。","大府尊官五色鞭，置酒高台打春破。","女魃吾知旱有神，神或汝矜民尚可。","里正夜走急如风，明日长官来劝农。"]},{"t":"采莲女","f":"楚辞体","c":["妾本鸳鸯湖上女，家在鸳鸯湖上住。","去年湖上采莲时，将身嫁作商人妇。","商人今年行不归，荷花欲语娇为谁。","閒看鸳鸯抛翠菂，颜色如花命如薏。","莲有藕兮藕有丝，郎君白面谁家儿。","水烟霏霏日催夕，解后相逢莫相忆。"]},{"t":"参沙神歌","f":"曲","c":["参沙之神铁作身，可以厌伏水怪降枫人。","去年汉盐官，地坼灵海垠。","龙鱼凭怒不可驯，潮汐奋决惊吾民。","南垣秉钧吏，飞书报天子。","有命恤民瘝，奇谋遂蜂起。","君不见临皋间，剥山及骨赭以殷。","山气靡靡去不还，山木惨惨愁无颜。","吴船衔尾七百里，共输山石填海水。","沙虚岸陨势莫支，虎落长筊非久计。","愚公于今无子孙，操蛇之神聩不闻。","徒知发鸠有鸟名精卫，衔冤蓄愤口欲弊。","参沙神，嗟尔有力赑屃如庚辰，便当为我桎梏疏属安朱垠。","海行故道从此始，民情快乐天心喜。","大刻穹碑纪神美，亿万斯年永无圮。"]},{"t":"题蘧庐小像","f":"楚辞体","c":["彼何人兮翩翩，衣白苧兮纯玄。","曳扶留之枯枝，若将去而复旋。","虎挟乙以谁威，龟藏六而自全。","合归休乎吾土，寄蘧庐以天年。"]},{"t":"四时木犀歌","f":"楚辞体","c":["山有木兮木有犀，其花长秋何皑皑。","灵芝三秀书上瑞，曾不及尔常芬菲。","初疑师文叩弦发清商，无射应律变四时。","又疑女夷司花窃天和，使尔枝格生妩媚。","物生根拨真自异，天情岂得为尔私。","蟾宫别种万万古，不与草木同凋萎。","安得灵风锵然驾鸾翼，与尔上结青云知。"]},{"t":"升平曲濮乐閒赏灯席上作","f":"曲","c":["歌升平，尔田多稼我庾盈。","姑苏台边灯作市，拦街小儿拜参星。","冰蚕作茧大如瓮，火鼠摛毫白成雪。","鲛人试手织轻绡，结束琉璃万明月。","月中五色花满围，交光相罗宝纹□。","□奴然炬夜不瞑，吹霞弄日摇春晖。","华屋煌煌耀深迥，龙脑浮香留藻井。","云母屏开火树花，水精帘泛金波影。","主人置酒清若渑，桃花扇底来娇应。","朝廷有道与民乐，制此一曲歌升平。"]},{"t":"种花吟","f":"曲","c":["满园种花不种桑，野桑不入名花谱。","五陵豪家纨裤儿，快乐岂知蚕绩苦。","欢娱未足事已垂，富贵欺人年少去。","却携锄钁向桑间，满眼看花花不语。","君不见金谷荒凉梓泽空，春风锦障俱尘土。","悔不当时学种桑，尽遣歌姬作蚕妇。"]},{"t":"赠陆松隐","f":"曲","c":["武陵刘郎花下歌，商雒黄公橘中乐。","隐居岂必巢云松，要在披襟有丘壑。","肘后长悬不老方，人间共爱长生药。","白发万丈吾何忧，可待流肪成琥珀。"]},{"t":"感怀","f":"曲","c":["百年如舜华，览之不盈把。","胡为蜗角争，流血遍原野。","不闻楚王孙，风雷生叱咤。","哀哉帐中歌，美人双泣下。","吟诗故不恶，饮酒亦大雅。","得失可忘言，富贵天所假。"]},{"t":"程祥甫南山篇","f":"曲","c":["南中有山何巑岏，崛起自是佳林峦。","不同躁者与物竞，长得幽人推户看。","乌皮旧几歙石砚，黄葛短衫湘竹冠。","此地烟霞足真赏，他家图画空美观。","尚怜䟤跋风尘下，俛首局促为盐官。","平生胸次故悠然，取琴囊中时一弹。","松头秀色近可挹，窗宇六月生苍寒。","便应许我分半榻，永矢弗谖歌考槃。"]},{"t":"题江山归兴图","f":"曲","c":["秦望东南远欲无，依稀禹穴向姚虞。","几时把酒鄞江上，却对乡山看此图。"]},{"t":"拟古","f":"曲","c":["龙马负灵图，八卦开人文。","天运当寅中，民时方大昕。","制字乃未多，所言为典坟。","一往数千载，怀哉圣神君。","翳林无阳土，暗谷多下泉。","登山履众险，险尽见杪颠。","人居物物中，物物能蔽天。","将身出物表，万象始昭然。","一气成岁功，孰为四分之。","遂使春木荣，不知秋叶萎。","天道自有初，物命亦有司。","任运得吾性，无为无不为。","天高九万里，疾若弩矢驰。","白日犹在下，况尔众物为。","翾羽刷俊彩，强欲凌空飞。","去人苦不远，但使见者疑。"]},{"t":"感怀","f":"曲","c":["积阴不可扫，积懑不可道。","君子所可道，小人以为嬲。","世事终渺茫，物情慢衰老。","归来日未昳，自去庭中草。","仙人大还丹，可用更凡胎。","举世不谓然，逝矣谁能哀。","万事唯有醉，奴子抱琴来。","十倍李供奉，一饮三千杯。","矩步恒彳亍，捷走能千回。","感彼元发化，聊复少衔杯。","阴草夏即苑，阳花冬亦开。","天序自有定，不是偶然来。","有酒可用醑，无酒我当酤。","天运岁益差，人事日不如。","羽虫何多言，木叶已无数。","凄其众草晚，乐与佳菊遇。","物蠹岂有极，造物难为工。","我将剔除之，刺芒铦若锋。","小枝食已尽，大枝旋复空。","虫多饱即死，花落为枯丛。","盆中梅树子，为尔可怜生。","寒泥不五斗，勿与大块争。","移置池水头，照影池上冫。","和冫嚼花蕊，天地无馀清。","娼鸟不可驯，娼女不可亲。","野性自难定，岂知爱其身。","千金买少妾，属托在他人。","譬如道旁花，竟是为谁春。","驽马少良驹，淑媛多令子。","大易重咸恒，关雎明谨始。","橘树生南州，渡江即为枳。","地气使之然，如何论天理。","江左言风流，王谢为称首。","谧既坐奸回，澹亦亏节守。","清谈本废事，何物非刍狗。","不忍书义熙，侃独有佳后。","子云投阁生，绿珠坠楼死。","事主心弗移，不若一婢子。","哀哀莽大夫，千古秽青史。","草元数万言，焉用识奇字。","燔肉既不至，孔子辄去鲁。","醴酒复不设，穆生亦辞楚。","古人道义交，政在慎出处。","寥哉圣贤心，夫岂餔啜故。","花开君勿折，花谢君勿扫。","扫花伤花心，折花畏花嫐。","但令尊有酒，中怀得倾倒。","从花自开谢，开好谢复好。","上客有冯驩，故吏有任安。","二子久已死，益见交道难。","软语相媚悦，颠倒若转丸。","孰云是可忍，怒发为冲冠。","南州辫发儿，相从事觚椠。","陈遵好尺牍，暇日聊口占。","悠悠历岁年，寒暑若病痁。","道德负初心，谁独受针砭。","客有千金儿，过我十尺舍。","狭隘不可留，飞丸出弹射。","腰下雕玉螭，粹好绝衅罅。","信美非所珍，聊足以相诧。","朱弦有遗音，琅然动清泛。","自喜若弗胜，入耳何沨沨。","君子道吾常，哤俗多杂儳。","但念赏人稀，不知听者厌。","白日何瞢瞢，人中有枭獍。","酖毒不可怀，犹将恣酣醟。","司命主督察，雷公布天令。","慎尔恐自戕，微我相诟病。","儒有席上珍，把玩足无厌。","梅花虽苦寒，其中自清赡。","富贵如燎毛，炙手方炎炎。","贪恋之谓何，仰天一长欠。","昂然三尺松，种之五斗盎。","俯身就嵌石，毛发如鬼状。","虽蒙华屋居，故性终木强。","谁当宣其郁，使彼得疏畅。","久客念还家，还家复如客。","行李未及安，期日相促迫。","勿匆问衣襟，草草箧书册。","终岁恒若斯，几何头不白。"]},{"t":"寄胡伯衡兼呈叔父元理元美二首","f":"曲","c":["忆昔少年日，慷慨赋远游。","晨起揽白须，始知天地秋。","寒云去雁断，落木穷猿愁。","亲故各异方，谁当慰淹留。","此邦非吾土，怅望登兹楼。","长歌动幽愤，汗漫不可收。","阳鸟尚谋食，候虫犹念衣。","口体见驱迫，使我远别离。","历历路半千，迢迢江两涯。","悠悠去乡邑，往往见絷縻。","年衰酒况恶，引饮不满卮。","形影相嘅惜，恐为时所悲。","弁山非故山，怆然寄幽期。","馀生苟木陨，犹及尔东归。"]},{"t":"寄衍上人索画兰","f":"曲","c":["薄言采兰蘤，兰叶□□□。","□□□人远，僻处荒山原。","崇炫非素心，澹泊性所存。","亦同桃李春，不同桃李繁。","众芳非不佳，蕙茝尤楚楚。","亦荷雨露私，如何在榛莽。","庶将展微劳，揽置群玉府。","时我方未遑，临风独延伫。","渔子荡两桨，来从湘水滨。","手抱青兰枝，言报山中春。","问我日日醉，恐贻楚叟嗔。","独醒不在酒，举手谢野人。","日出跻北林，日入下西澨。","幽芳隔远水，水寒不可厉。","归来看画图，潇洒美风制。","万事何必真，聊与尔同世。"]},{"t":"游幻住庵留赠月千江上人","f":"曲","c":["出郭动柔橹，春花始班班。","俯舷照清流，正见衰病颜。","形影自相笑，浮沉人两间。","胡能即有定，波荡不得閒。","村雨农事殷，溪晴客衣暖。","佳人同綵舟，沿洄绕芳甸。","吴蚕近三眠，鲁桑连百畹。","相将采白蘋，日与春俱晚。","既雨天复佳，鸣鸟声故故。","前溪春已深，劝我脱布裤。","刺篙乱清涟，艇子入浦溆。","我裤不用脱，汝自顾汝妇。","维时桃始华，野眺欣有睹。","沿洄度桑隰，迤逦见谷土。","山虚龙出云，谷暖鸟鸣雨。","来耨良足勤，力薄奈何汝。"]},{"t":"题画山水似盛子昭","f":"曲","c":["冉冉山上云，累累水中石。","梢梢林莽高，黯黯崖谷黑。","东冈特秀绝，拔地起千尺。","突兀众峰间，犹是太古色。","连山根插江，江碧石齿齿。","层颠高出云，老树下压水。","岩扉俯深迥，磴道陟纡委。","欲持一壶酒，慰彼幽栖子。","前山如立槊，后山如倚较。","远近千万山，斗绝入牛角。","矾头积磊砢，石面斗硗确。","是中无征徭，民俗犹愿悫。","回峰危欲堕，峭径深可入。","萦纡度壁坞，杳窕去井邑。","泉悬净练明，崖拥积铁涩。","缅怀贞白君，相从负云笈。"]},{"t":"雪壑海云使君所自号也","f":"曲","c":["云来雪壑阴，云去雪壑明。","未见雪壑面，已闻雪壑名。","岂谓众皆浊，常使我独清。","云去雪壑明，云来雪壑阴。","不从雪壑游，不知雪壑心。","家世本钟鼎，志愿在山林。"]},{"t":"次韵曹教谕见寄","f":"曲","c":["凉风发秋夕，落木振疏阴。","相思在咫尺，两契同一心。","徽弦不下指，宁我有遗音。","梧桐生下泽，几时成凤林。","蹀躞双远游，独绕庭中树。","与世欲并臧，行行迷所遇。","有客吹洞箫，如泣亦如诉。","花月满良宵，如何此虚度。"]},{"t":"弟玮来奔父丧写忧四首","f":"曲","c":["弟从江东来，沉痾仅能起。","恸哭我先人，旅榇在千里。","丧期岂无数，佣力方有俟。","人命终若倚，吾衰复如此。","堕泪下承睫，览镜拂铅水。","昔者母教儿，过于我严君。","至今清夜中，梦想见劳勤。","深恩久未报，白发纷如耘。","扬名不及显，痛恨思遗训。","孝养岂有足，促促岁月驶。","承欢顺颜色，万一有不至。","靖言念前非，良悔亦已迟。","更敢责后人，聊使后人知。","去年被群偷，终岁不得宁。","讫今觊小康，大忧重相仍。","蒺藜不可据，荼蓼不可茹。","兹事未易了，兴哀欲谁语。"]},{"t":"赋竹居","f":"曲","c":["好风从东来，吹我石上竹。","取琴竹下弹，希声不成曲。","桃李正无言，世人自相逐。","繁华此何时，所贵君子独。","残棋久未收，竹凉成小坐。","樵苏冷不爨，所设惟瓜蓏。","风吹碧云动，时有苍雪堕。","焉知人间世，赤日如焦火。","远过幽人居，支筇立良久。","竹影落秋波，照面绿于酒。","俗士不必来，屐齿苍苔厚。","案头二王书，妙不数颜柳。","好画不厌看，奈此风凄洌。","翠禽双飞来，翻枝落残雪。","竹间见石友，岁晚共贞节。","淡如君子交，冷面炙不热。"]},{"t":"送礼绝学上人还下渚","f":"曲","c":["西游五天竺，东上三神山。","相去各几许，悠悠生死关。","我欲往从之，忘世良复难。","大道固无为，此身要勿閒。","乾坤性吾德，父母形我颜。","壮志方未酬，努力更加餐。","落叶飞清霜，长飙薄林樾。","青山频梦归，夜半孤舟发。","宁无金错刀，呼酒与君别。","歘来语匆匆，径去心孑孑。","清溪今夜寒，梅花满篷雪。","相思曲未终，冻琴弦欲折。"]},{"t":"顾德玉万竹轩","f":"曲","c":["日出尘未动，清坐傍疏帘。","帘影带深竹，风漪摇四檐。","花时甘澹退，寄怀在棋奁。","举手属有念，食子乃久拈。","壁间棕毛拂，窗下漆棐几。","一尘飞不来，竹色净于水。","宾退日更长，清风亦时至。","兰亭脩禊辞，硬黄临茧纸。","白日何促促，秋灯动华屋。","所思浩无端，开轩坐幽独。","凉月出东楹，琴声隔深竹。","欲问弹者谁，童子睡正熟。","江晚雪初集，翠竹声珊珊。","晓超当南荣，飞舞万玉鸾。","爱此不能去，岂知双袂寒。","欲招丹渊子，写作图簇看。"]},{"t":"写愁似胡伯亮","f":"曲","c":["阳元外家儿，生世何酷似。","两翁幸无虞，二母俱已矣。","青云难与期，白日非可恃。","动止见羁束，晨昏阙娱侍。","鸣雨清夜长，野蔌剪畦翠。","苦语出肺肝，屡饮成恶醉。","兀兀鸡在栖，惴惴狐涉水。","处身百不可，在世一何累。","平生结发妻，疾势方未止。","芝苓笼中物，倾倒已屡试。","无宁作鳏夫，儿女欲何恃。","哽咽不得言，残烛泫风泪。"]},{"t":"梁邦彦王官谷见访","f":"曲","c":["伯鸾不愿仕，叔度亦无官。","葛越制隐服，竹皮裁小冠。","所求年谷成，斯人获苟安。","庶有一亩宫，可以歌考槃。","蚤起理素发，良朋来合并。","拂床正书册，整襟候门衡。","无忌酷似舅，季方难为兄。","朝阳双凤凰，文彩生光荣。"]},{"t":"留石门待内弟子经不至","f":"曲","c":["乘舟驾言迈，长夜方曼曼。","苍凉物华老，趢趗年景换。","顾予远适子，庶与同馆粲。","近行乃未来，久别良足叹。","飞鸟有遗音，啁鸣念故乡。","长风铩羽翮，回薄空翱翔。","顾我日衰迈，乐子年富强。","飘零岂不远，死生贵勿忘。"]},{"t":"读唐史","f":"曲","c":["汾阳国大臣，堂堂负才器。","独马不衷甲，气压天骄子。","鬼貌且蓝色，顾独畏卢杞。","刘晏工理财，国用得无乏。","凡皆属士类，吏独抱成牒。","政要在养民，其事故可法。","昔者冯瀛王，始事沙陀君。","延缘入汉周，常为将相臣。","每当革命日，必有劝进文。","元载既伏诛，胡椒八百斛。","钱圜以函方，善走固无足。","不闻古宥卮，既盈终必覆。","常闻阿荦山，窃弄梨园部。","其中有驯象，宁死终不舞。","遂与雷海青，垂名照千古。","娄公有盛德，与物澹无忤。","狄相才独雄，可用安国步。","我其举所知，不必知我举。"]},{"t":"惠山纪游二首","f":"曲","c":["跨马北郭门，寻僧南朝寺。","青云珠树林，碧草金沙地。","危径缘磥砢，寒泉写苍翠。","星垂析木光，月堕方诸泪。","含晖白日閒，动影清风起。","解瓢贮冷冽，临流浣尘滓。","九龙发灵渊，下作梁溪水。","文采多清流，波澜有源委。","我本乘兴来，岁事亦徂只。","汲此山中绿，寄彼城居子。"]},{"t":"吴兴杂咏十六首 石林精舍","f":"曲","c":["精舍青山曲，石林云气寒。","夔龙方满朝，谁不爱王官。","归人独有见，聊复此盘桓。","仙人白玉蟾，题诗留素壁。","笔势来翩翩，矆睒不可测。","将飞蛟龙影，或是风雨迹。","昔贤读书处，今为梵王宫。","世事有翻覆，人境谁能同。","唯应姓何氏，与山相始终。","污樽几千载，长在岘山硕。","何必有杯勺，聊为饮一杯。","落叶堕西风，奈此天地秋。","碧澜堂下水，浪波何沄沄。","远愧六客词，有感在斯文。","回舟唱歌去，弄影前溪云。","城郭俯寒碧，水木摇青华。","双双翡翠羽，低拂白蘋花。","如何杨刺史，不向此为家。","渺渺碧浪湖，中有浮玉山。","相期采兰若，佳人殊未閒。","舟楫忽已晚，乘风聊独还。","恭惟颜太师，名节天下无。","身首可异处，贞心终不渝。","客来拜祠下，岂爱干禄书。","古来贵书迹，莫如淳化年。","千金购遗帖，墨妙生姿妍。","谁其作亭子，宋人苏谪仙。","褰裳涉危楼，倚槛对雄州。","山横太湖口，溪出少城头。","阑干十二曲，清风如凉秋。","携酒上碧岩，挈壶松下饮。","凭高数千尺，云水白淰淰。","六月生夜寒，山眠不成寝。","孤塔倚晴霄，下瞰万顷陂。","升高欲望远，未至足已疲。","怀哉尚方舄，双凫正齐飞。","越俗好巫鬼，白鹤乃有神。","庙享非一朝，山木已千春。","客行亦少憩，焉知伪与真。","旱日赤如火，黄龙呼不应。","摇石动云气，听松作雨声。","怅望但空归，何以慰深情。","夫槩名王渚，西山紫笋茶。","水硙生绿尘，小角装金花。","尽从天使去，供奉内人家。","客来栖贤里，愿斸栖贤地。","秋来多晚菘，脆美敌群饩。","聊将遗子孙，庶能知此味。"]},{"t":"山水小景四幅","f":"楚辞体","c":["江有水兮水有波，龙鱼帖息兮风日美和。","望青山兮如眉而蛾，抚佳木兮以婆娑。","山出云兮不为霖雨，江有木兮不任楣柱。","朝余东冈兮莫余南浦，时乎时兮奈何汝。","洞庭波兮山崨嶪，川可济兮不可涉。","木兰为舟兮桂楫，渺余怀兮风一叶。","山之凹兮水之汇，沙棱棱兮石礌礌。","有美一人兮如彼兰茝，思之不来兮使我心痗。"]},{"t":"薄薄酒奉别吴季良二首","f":"曲","c":["薄薄酒，可杯勺，粗粗布，宜浣濯，丑妇耐贫勤织作。","我无南阳诸葛田，赤手欲探蛟龙渊。","曲中箜篌十四弦，河水东流心惘然。","角上蜗牛且酣战，鹤胫自长凫自短。","井蛙海鳖相讥嘲，何似雕鴳俱逍遥。","八珍之味不如良友，千金之富不如佳儿。","百年一息万世痴，庞公未为无所遗。","南山有木木有枝，根如盘石不可移。","薄酒味薄情不薄，丑妇貌丑心不丑。","君不见天下风流朱伯厚，车如鸡栖马如狗。","河西蒲桃紫雪浆，秦中琵琶妩媚娘。","黄金快意一日乐，奄忽百岁如风狂。","天雨未休匏叶苦，江湖水深不可渡。","豫章非?众莫辨，橀榽似檀人伐汝。","汉阴丈人抱瓮归，万事反覆非一机。","博劳东去燕西飞，毋与寸草争馀晖。"]}]};